/**
 * How to perform each exercise and what good form looks like, keyed by slug.
 *
 * A separate file from exercises.ts rather than an 8th pipe column there: the
 * pipe-delimited catalogue has no way to escape a `|` or a newline, and these
 * run 500-900 characters of prose each — cramming that into the catalogue's
 * one-line-per-exercise format would destroy the scannability its own doc
 * comment exists to protect.
 *
 * Generated by `npm run generate:exercise-descriptions` (see
 * scripts/generate-exercise-descriptions.ts), which is resumable and writes
 * this file back after every batch — re-running it only fills in whatever's
 * still missing. `npm run seed:exercises` merges these into the `exercises`
 * table's `description` column.
 *
 * General training guidance, not medical advice.
 */
export const EXERCISE_DESCRIPTIONS: Record<string, string> = {
  "45-degree-back-extension": "A bodyweight hinge performed on an angled bench that targets the glutes and hamstrings while reinforcing a strong lower back position. The hips rest on the pad with the body angled downward, and the torso lowers and raises by folding and extending at the hips.\n\n- Hinge at the hips, not the lower back, keeping the spine neutral throughout\n- Lower until you feel a stretch in the hamstrings, then squeeze the glutes to rise\n- Keep the bar or weight held close to the chest if adding load\n- Avoid hyperextending at the top; stop at a straight line from head to heel\n- Move under control rather than swinging up using momentum",
  "ab-wheel-rollout": "A challenging core exercise using an ab wheel to roll the body forward from a kneeling or standing position, requiring the abs and lats to resist spinal extension as the body extends outward. It builds anti-extension core strength and shoulder stability.\n\n- Kneel on a pad and grip the wheel handles with hands under the shoulders\n- Brace the core hard before rolling forward slowly, keeping the hips from sagging\n- Roll out only as far as you can control while maintaining a straight line from knees to head\n- Pull back to the start position using the abs and lats rather than the lower back\n- Keep the arms relatively straight and avoid letting the hips pike up during the roll",
  "arnold-press": "A rotational dumbbell shoulder press that starts with palms facing you and finishes palms forward, adding a supination twist through the range to hit the front and side delts from multiple angles. It's a compound vertical push that also demands triceps involvement to lock out overhead.\n\n- Start seated or standing with dumbbells at shoulder height, palms facing your body, elbows in front of your chest\n- Rotate your palms outward as you press, finishing with arms extended and palms facing forward\n- Keep your core braced and avoid arching your lower back as the weights pass overhead\n- Reverse the rotation smoothly on the way down, returning to the curled starting position\n- Control the descent rather than letting the dumbbells drop",
  "back-extension": "A bodyweight isolation exercise performed on a hyperextension bench, targeting the lower back with assistance from the glutes and hamstrings. It trains controlled hip and spinal extension and is commonly used to build posterior chain endurance and strength.\n\n- Position your hips on the pad with your ankles secured and torso hanging forward\n- Cross your arms over your chest or hold them behind your head\n- Lower your torso by hinging at the hips until you feel a stretch in the hamstrings\n- Raise your torso back up until your body forms a straight line, avoiding hyperextending the spine at the top\n- Keep movements controlled and avoid using momentum to jerk upward",
  "back-squat": "A foundational compound lift where a barbell is racked across the upper back and the lifter squats down and stands back up, loading the quads, glutes, and hamstrings together. It's a core movement for building lower-body strength and mass and serves as the base pattern for its bar-position variations.\n\n- Set the bar on the upper traps or rear delts and grip it just outside shoulder width\n- Brace the core and unrack with feet set at hip to shoulder width\n- Break at the hips and knees together, sitting down and back while keeping the chest up\n- Descend to at least parallel with knees tracking over the toes\n- Drive through the whole foot to stand, keeping the bar path vertical over the midfoot",
  "band-pull-apart": "A simple resistance-band exercise that pulls the band apart in front of the body to work the rear delts and upper back. It requires minimal equipment and is often used as a warm-up or accessory movement for shoulder health.\n\n- Hold the band with both hands at shoulder width, arms extended in front at chest height\n- Pull the band apart by driving the hands out to the sides, keeping the arms straight\n- Squeeze the shoulder blades together as the band reaches the chest\n- Keep the core braced and torso upright without arching the back\n- Return the band under control rather than letting it snap back",
  "banded-lateral-walk": "A standing isolation drill that uses a resistance band around the legs or ankles to challenge the hip abductors and glutes as you step sideways. It's often used as an activation or accessory movement for the hips.\n\n- Place the band around the ankles or just above the knees and set feet hip-width apart\n- Bend the knees slightly and sit into a mini-squat position throughout\n- Step sideways under control, keeping tension on the band at all times\n- Avoid letting the knees cave inward or the feet turn out\n- Take deliberate, controlled steps rather than letting the band pull the legs together",
  "barbell-bench-press": "A foundational horizontal pressing movement performed lying on a flat bench, driving a loaded barbell from the chest to full arm extension. It builds pressing strength and mass through the chest, shoulders, and triceps and serves as a benchmark upper-body lift.\n\n- Set feet flat on the floor, arch slightly through the upper back, and pull shoulder blades down and together before unracking\n- Grip the bar slightly wider than shoulder width and keep wrists straight over the forearms\n- Lower the bar under control to the mid-chest, keeping elbows at roughly a 45-75 degree angle from the torso\n- Drive the bar back up in a slight arc toward the shoulders, keeping feet planted and hips on the bench\n- Avoid bouncing the bar off the chest or letting the elbows flare straight out to the sides",
  "barbell-curl": "A classic biceps isolation exercise performed by curling a loaded barbell from the thighs to the shoulders, also placing demand on the forearms through the gripping and stabilizing action. It's a staple for building arm size and strength.\n\n- Stand with feet shoulder-width apart, holding the bar with an underhand shoulder-width grip\n- Keep elbows pinned to your sides throughout the movement\n- Curl the bar up by flexing at the elbow, avoiding swinging the torso\n- Squeeze the biceps at the top before lowering under control\n- Lower the bar fully to straighten the arms each rep",
  "barbell-high-pull": "An explosive pulling movement where the bar is driven upward from the hips to roughly chest height using hip extension and a vigorous arm pull, targeting the traps and side delts. It's often used to build the finishing pull power needed in Olympic lifting movements.\n\n- Start in an athletic hinge position with the bar close to the thighs\n- Extend the hips explosively first, then pull the elbows high and outside\n- Let the bar travel close to the torso as it rises toward the chest\n- Keep the wrists relaxed and let the elbows lead the pull\n- Avoid muscling the bar up with the arms before the hips have finished extending",
  "barbell-row": "A classic hip-hinge horizontal pull where a loaded barbell is pulled from a hang toward the torso, building thickness in the upper back, lats, and grip strength along with the biceps. It's a staple compound movement for developing overall pulling strength and posture.\n\n- Hinge at the hips with a flat back, knees slightly bent, torso angled roughly 45 degrees to the floor\n- Grip just outside shoulder width and let the bar hang at arm's length before pulling\n- Drive elbows back and pull the bar toward the lower ribs or upper abdomen\n- Keep the torso angle fixed throughout the set instead of using it to heave the weight\n- Lower the bar under control back to a full stretch each rep",
  "barbell-shrug": "An isolation movement for the trapezius performed by lifting a loaded barbell straight up using the shoulders, with grip strength from the forearms also challenged. It's a straightforward way to add size and strength to the upper traps.\n\n- Hold the bar with an overhand grip just outside the hips\n- Stand tall with a neutral spine and braced core\n- Elevate the shoulders straight up toward the ears without rolling them\n- Pause briefly at the top and squeeze the traps\n- Lower under control rather than dropping the weight",
  "barbell-split-squat": "This is the split squat pattern performed with a barbell across the upper back instead of dumbbells, allowing for heavier loading of the quads and glutes in a stationary staggered stance. It demands solid core bracing and hip stability since the load sits on the spine rather than the hands.\n\n- Set the bar in a comfortable back rack position and step into a split stance\n- Keep the front foot flat and the back heel raised, with the feet hip-width apart for balance\n- Lower under control until the back knee nearly touches the ground, keeping the torso upright\n- Avoid letting the front knee drift excessively past the toes or cave inward\n- Drive through the front leg to stand, keeping the bar path vertical",
  "bayesian-cable-curl": "A unilateral biceps curl performed standing with the body positioned in front of a low cable, arm starting extended behind the torso. This starting position creates a unique stretch on the biceps at the bottom, making it effective for building length-tension strength in the muscle.\n\n- Stand facing away from the pulley with the working arm extended back behind your hip\n- Keep the elbow pointed down and slightly behind the torso throughout the curl\n- Curl the handle up and forward, focusing on peak contraction at the top\n- Control the return to the stretched starting position without letting the cable yank the arm back\n- Avoid rotating the torso to assist the lift",
  "behind-the-neck-press": "A pressing variation where the bar starts behind the head rather than in front, shifting more of the load onto the side delts and requiring greater shoulder mobility to perform safely and comfortably. It's typically used by lifters with adequate shoulder range of motion looking to target the lateral deltoid differently than a front press.\n\n- Set the bar on the traps behind the neck, hands wider than shoulder width\n- Keep the torso upright and core braced before pressing\n- Press the bar straight up overhead, avoiding excessive forward or backward head movement\n- Lower the bar under control back to the base of the neck\n- Only use a range of motion that feels controlled and comfortable at the shoulder",
  "belt-squat": "A squat variation performed wearing a belt attached to a loaded frame or machine, positioning resistance at the hips instead of on the spine. This shifts the load onto the legs, training the quads and glutes with reduced compressive stress through the upper body.\n\n- Stand on the raised platform with feet shoulder-width apart and belt attachment hanging freely below\n- Keep the torso upright and braced rather than leaning to compensate for the hip-level load\n- Squat down until thighs reach parallel or your comfortable depth, keeping knees tracking over toes\n- Drive up through the whole foot, avoiding rising onto the toes\n- Keep the descent controlled rather than dropping quickly into the bottom position",
  "bench-dip": "A bodyweight isolation exercise performed with hands behind you on a bench and feet extended out, lowering the hips toward the floor by bending the elbows. It primarily works the triceps with secondary involvement from the front shoulders.\n\n- Place hands on the edge of a bench with fingers pointing forward, feet out in front\n- Lower the hips straight down by bending the elbows to roughly ninety degrees\n- Keep the torso close to the bench rather than drifting forward\n- Press back up through the palms until the arms are extended\n- Keep shoulders down away from the ears throughout the movement",
  "block-pull": "A deadlift variation performed with the barbell elevated on blocks, reducing the range of motion similarly to a rack pull but often starting slightly lower, targeting the hamstrings and glutes through a stronger, more controlled pulling range. It's useful for reinforcing lockout strength and positioning.\n\n- Set the bar on blocks so it sits a few inches above the floor\n- Set up with a flat back, shins close to the bar, and hips slightly higher than in a full deadlift\n- Brace your core and drive through your legs to initiate the pull\n- Keep the bar close to your body as it travels up past the knees\n- Finish by driving the hips through and standing fully upright",
  "board-press": "A partial-range bench press performed with one or more boards placed on the chest to limit how far the bar descends, allowing focus on the top portion of the press and heavier overload for the triceps and lockout strength. It's commonly used by lifters looking to strengthen sticking points near full extension.\n\n- Have a partner hold or secure the boards steady on the chest, or use a strapped set if training alone\n- Lower the bar under control until it lightly touches the boards, then pause briefly\n- Keep elbows tracking under the wrists rather than flaring wide during the descent\n- Drive the bar explosively off the boards, focusing on locking out the elbows fully\n- Maintain the same shoulder blade retraction and foot drive used in a full-range bench press",
  "box-jump": "A plyometric exercise where the lifter jumps from the ground onto an elevated box or platform, developing explosive power in the quads and calves along with coordination and landing control. It's commonly used to build lower-body power output without the eccentric loading of running-based plyometrics.\n\n- Stand a comfortable distance from the box with feet shoulder-width apart\n- Swing the arms back then forward while dipping into a quarter squat before jumping\n- Drive through the legs and extend fully in the air, pulling the knees up toward the box\n- Land softly on the box with knees bent and feet flat\n- Step down rather than jumping back down to reduce unnecessary impact",
  "box-squat": "A back squat performed by sitting back onto a box or bench and pausing before standing, used to reinforce hip-hinge mechanics and control depth. It's a common tool for building starting strength off a dead stop and teaching a controlled, deliberate descent.\n\n- Set the box height so the hips reach just at or slightly below knee level\n- Sit back with hips leading, keeping shins closer to vertical\n- Touch the box lightly and pause briefly without relaxing the hips or bouncing\n- Keep tension in the core and legs throughout the pause\n- Drive up powerfully from the box, leading with the hips",
  "bradford-press": "A continuous pressing drill where the bar is alternately pressed partway overhead and lowered behind the head without full lockout, keeping constant tension on the shoulders. It emphasizes the front and side delts along with the triceps through a shortened, controlled range of motion.\n\n- Start with the bar at the front of the shoulders, hands just outside shoulder width\n- Press the bar up and slightly back, stopping short of full lockout, then lower it behind the head to shoulder height\n- Reverse direction, pressing back up and over to the front, again stopping short of lockout\n- Keep the movement smooth and controlled rather than rushed\n- Maintain a tight core and upright torso throughout the continuous motion",
  "broad-jump": "A horizontal jumping movement that trains explosive hip extension and total-body power through the glutes and quads, requiring the lifter to jump forward for maximum distance rather than height. It's a staple test and training tool for lower-body power and coordination.\n\n- Start with feet shoulder-width apart, hinging at the hips and swinging the arms back to load\n- Drive the arms forward explosively while extending the hips, knees, and ankles\n- Aim to travel as far forward as possible before extending fully in the air\n- Land softly with bent knees and hips absorbing the impact\n- Stick the landing under control before resetting for the next rep",
  "bulgarian-split-squat": "A single-leg squat performed with the rear foot elevated on a bench, this exercise loads the front leg heavily while reducing the base of support, building quad and glute strength along with balance. Dumbbells are held at the sides to add resistance.\n\n- Position the rear foot on a bench behind you, laces down, with the front foot far enough forward to keep the knee tracking over the toes\n- Lower straight down until the front thigh is close to parallel with the floor\n- Keep most of the bodyweight on the front leg, using the rear leg mainly for balance\n- Maintain an upright torso and avoid letting the front knee cave inward\n- Push through the front heel and midfoot to stand back up",
  "cable-crunch": "A kneeling cable exercise that loads spinal flexion directly, letting the abs work against constant tension through a full range of motion. It's a popular way to add resistance to the basic crunch pattern once bodyweight variations become too easy.\n\n- Kneel below the cable with the rope or handle held near the head or shoulders\n- Hinge at the hips slightly to set up, then flex the spine to crunch down\n- Focus on curling the ribcage toward the pelvis rather than pulling with the arms\n- Keep the hips relatively fixed so the movement comes from the trunk\n- Control the return to the top without letting the weight stack slam",
  "cable-curl": "A biceps curl performed with a cable and bar or rope attachment, providing constant tension throughout the entire range of motion unlike free weights. This steady resistance challenges the biceps and forearms even at the top and bottom of the movement where dumbbells or barbells go slack.\n\n- Stand facing the pulley with a slight forward lean and elbows fixed at your sides\n- Curl the attachment up while keeping the upper arms stationary\n- Squeeze the biceps at the top of the movement\n- Lower slowly to maintain tension rather than letting the cable snap back\n- Keep your torso still, avoiding hip drive or backward lean to move the weight",
  "cable-fly": "An isolation exercise performed standing between two cable stacks, bringing the handles together in front of the chest through a wide arcing motion. It targets the chest directly with constant tension throughout the range of motion, unlike free-weight flys.\n\n- Set both pulleys to chest height and take a staggered stance for stability\n- Start with arms extended out to the sides, a slight bend maintained in the elbows\n- Bring the handles together in front of the chest in a hugging arc motion\n- Squeeze the chest at the point where hands meet, then return under control\n- Avoid using momentum or letting the arms travel too far behind the body",
  "cable-front-raise": "A front raise done with a low cable pulley, providing constant tension on the front delts throughout the range of motion, unlike the dumbbell version where tension drops at the top. A single handle or rope attachment is typically used.\n\n- Stand facing away from the low pulley, handle in one hand at the hip\n- Raise the arm forward to shoulder height with a slight elbow bend\n- Keep the shoulder down and avoid shrugging as the arm rises\n- Control the lowering phase to maintain tension\n- Keep the torso stable without rocking to assist the lift",
  "cable-glute-kickback": "A unilateral cable exercise that isolates the glutes and hamstrings by extending the hip against resistance from a low cable pulley. It's typically done with an ankle cuff attachment while facing the machine.\n\n- Attach the cuff to the ankle and hinge slightly forward from the hips, holding the frame for support\n- Kick the working leg straight back, driving through the heel and squeezing the glute at end range\n- Keep the standing leg slightly bent and the core braced to avoid arching the lower back\n- Move through a controlled range without swinging the leg using momentum\n- Return the leg slowly to the start position rather than letting the cable snap it back",
  "cable-lateral-raise": "A side delt isolation exercise performed with a low cable pulley, providing constant tension throughout the entire range of motion unlike free weights where tension drops near the bottom. This makes it effective for maximizing time under load on the shoulder.\n\n- Stand side-on to the cable machine with the pulley set low and grip the handle with the far hand\n- Raise the arm out to the side to about shoulder height, leading with the elbow\n- Keep a slight bend in the elbow throughout and avoid rotating the torso to assist the lift\n- Control the descent back down against the cable resistance rather than letting it snap back\n- Keep the shoulder down away from the ear rather than shrugging during the raise",
  "cable-pull-through": "A cable-based hip hinge that uses constant tension to train the glutes and hamstrings while teaching a controlled hinging pattern. Standing facing away from the cable stack, the rope is pulled between the legs by driving the hips forward.\n\n- Stand tall with feet shoulder-width apart, cable anchored low behind you\n- Hinge at the hips, letting the rope pull back between your legs while keeping knees soft\n- Keep the spine neutral and chest up as you fold forward\n- Drive the hips forward to stand tall, squeezing the glutes at the top\n- Avoid rounding the back or turning the movement into a squat",
  "cable-rear-delt-fly": "A rear delt fly performed using crossed cables at chest height, pulling the handles out and back to target the posterior deltoids and upper back. The cable setup keeps constant tension on the muscle through the full range of motion.\n\n- Set two pulleys to roughly chest height and cross the cables, grabbing the opposite handle with each hand\n- Stand with a slight forward lean and soft knees, arms extended in front\n- Pull the handles out and back in an arcing motion, leading with the elbows\n- Squeeze the shoulder blades together at the end of the movement\n- Control the return to the starting position without letting the weight stack slam",
  "cable-shrug": "A trap isolation exercise using a cable machine to provide constant tension throughout the shrugging motion, unlike free weights where tension can ease at the bottom. It's useful for keeping continuous load on the traps.\n\n- Stand facing or away from the stack depending on attachment setup, holding the handle(s) with straight arms\n- Keep a tall posture with the core braced\n- Lift the shoulders straight up toward the ears\n- Avoid using the arms or momentum to help raise the weight\n- Lower slowly to maintain tension before the next rep",
  "cable-upright-row": "An upright row performed with a low pulley cable and straight bar or handle, providing steady tension as the weight is pulled vertically along the body to work the side delts and traps. The cable setup can make the resistance curve feel different from a barbell version.\n\n- Stand facing the low pulley with a straight bar or rope handle, arms extended down\n- Pull the handle straight up along the torso, leading with the elbows\n- Keep the bar or handle close to the body throughout the movement\n- Avoid excessive shrugging and let the delts and traps drive the pull\n- Lower under control to full arm extension before the next rep",
  "cable-woodchopper": "A rotational cable exercise that mimics a chopping motion, training the obliques and core to produce and control diagonal force through the trunk. It also involves the hips and shoulders as the movement crosses the body.\n\n- Set the cable high or low depending on the chop direction desired\n- Stand with feet shoulder-width apart and rotate the torso to pull the handle across the body\n- Pivot the back foot and rotate through the hips and trunk together\n- Keep arms relatively straight so the movement comes from rotation, not just arm pulling\n- Control the return back to the starting position rather than letting the cable snap the arms back",
  "california-press": "A close-grip bench press variation that lowers the bar toward the lower chest or upper abdomen with elbows tucked, extending the range of motion to emphasize the triceps while still training the chest. It bridges the gap between a standard bench press and a skull crusher.\n\n- Set up on a flat bench with hands closer than a standard bench press grip\n- Lower the bar slowly toward the lower chest or upper abs, keeping elbows tucked\n- Press back up in a slight arc toward the shoulders to finish the lockout\n- Keep shoulder blades retracted and feet planted for a stable base\n- Avoid letting elbows flare wide, which shifts stress away from the triceps",
  "chest-dip": "A bodyweight pressing exercise performed on parallel bars, leaning the torso forward to emphasize the chest while also working the triceps and front delts. It builds pressing strength through a deep range of motion at the shoulder joint.\n\n- Grip the bars and support the body with arms extended, leaning the torso forward\n- Lower the body by bending the elbows until the upper arms are roughly parallel to the floor\n- Keep the elbows flaring slightly outward and shoulders relaxed away from the ears\n- Press back up to full extension without shrugging the shoulders\n- Control the descent rather than dropping quickly into the bottom position",
  "chest-supported-row": "A horizontal pull performed lying chest-down on an inclined bench, which removes the need to stabilize the lower back and isolates the upper back and lats through a strict pulling motion. This setup is useful for targeting back musculature without any assistance from hip or leg drive.\n\n- Lie chest-down on the pad with dumbbells hanging at arm's length below the shoulders\n- Keep the chest pinned to the bench throughout the set rather than lifting off to cheat the rep\n- Pull the elbows back and slightly up, squeezing the shoulder blades together at the top\n- Lower the dumbbells under control to a full stretch before the next rep\n- Keep the neck neutral and avoid craning the head up to see the weights",
  "chin-up": "A bodyweight vertical pull performed with an underhand grip on a fixed bar, pulling the chest up toward the hands. It builds the lats heavily while giving the biceps a large secondary role due to the supinated grip.\n\n- Grip the bar shoulder-width or slightly narrower, palms facing you\n- Start from a dead hang with shoulders engaged, not fully passive\n- Pull elbows down and back, driving them toward your hips\n- Lead with the chest and touch the bar near collarbone height\n- Lower under control to a full hang rather than dropping quickly",
  "clean-and-jerk": "A two-part Olympic lift combining a clean to bring the bar to the shoulders with a jerk that drives it overhead using leg drive and a split or squat stance. It's one of the most demanding tests of full-body power, coordination, and overhead stability.\n\n- Perform the clean by pulling the bar from the floor and receiving it in a front-rack quarter-squat, then standing tall\n- Reset the bar on the shoulders with the elbows up and chest tall before jerking\n- Dip straight down slightly, then drive explosively upward, punching the bar overhead\n- Split or squat under the bar to receive it with arms locked out overhead\n- Bring the feet back together and stand fully to complete the lift",
  "clean-pull": "A partial Olympic lift movement that mimics the pulling phase of the clean without the catch, used to build explosive hip extension and pulling strength through the traps and hamstrings. It allows heavier loads than a full clean since there's no need to receive the bar in a front rack.\n\n- Set up with the same stance and grip as a clean, hips high and back flat\n- Drive the floor away with the legs before aggressively extending the hips\n- Finish tall on the toes with a strong shrug, keeping the bar close to the body\n- Avoid excessive arm bend; the pull should come from the legs and hips, not the biceps\n- Control the bar back down rather than letting it crash to reset position",
  "close-grip-bench-press": "A bench press variation using a narrower grip, roughly shoulder-width or slightly inside it, that shifts the load onto the triceps while still involving the chest and front delts. It's a staple for building pressing power and arm strength.\n\n- Grip the bar with hands about shoulder-width apart, thumbs wrapped for control\n- Keep elbows tracking close to the torso as the bar descends, rather than flaring out\n- Lower the bar to the lower chest or sternum with a controlled tempo\n- Drive through the palms and extend the elbows fully at the top without losing bar path\n- Maintain a stable arch and tight upper back just as with a standard bench press",
  "close-grip-lat-pulldown": "A lat pulldown performed with hands close together, often on a V-bar or narrow attachment, allowing a longer pulling range and greater bicep contribution. This grip lets many lifters pull heavier loads through a fuller range.\n\n- Use a close neutral or narrow overhand grip on the attachment\n- Keep elbows tracking close to the torso as they descend\n- Pull the handle to the lower chest, driving elbows down and back\n- Avoid using body English or excessive backward lean to move the weight\n- Extend fully at the top to stretch the lats before the next pull",
  "concentration-curl": "A seated, single-arm dumbbell curl where the elbow is braced against the inner thigh, isolating the biceps with minimal assistance from other muscles. The braced position allows for a strict, controlled curl with a strong mind-muscle connection.\n\n- Sit on a bench with legs spread, bracing the working elbow against the inner thigh\n- Let the arm hang straight down holding the dumbbell before curling\n- Curl the weight up smoothly without rocking the torso or shoulder\n- Pause and squeeze at the top of the range\n- Lower fully under control until the arm is straight again",
  "conventional-deadlift": "The conventional deadlift is a hip-hinge movement performed with a shoulder-width stance, pulling a loaded barbell from the floor to a standing lockout. It builds strength through the hamstrings, glutes, and lower back and is a foundational test of total-body pulling strength.\n\n- Set up with feet hip-width apart, shins close to the bar, and grip just outside the knees\n- Set the back flat and brace the core before initiating the pull\n- Drive through the floor with the legs while keeping the bar close to the shins\n- Extend the hips and knees together to lock out at the top without hyperextending the back\n- Lower the bar by hinging at the hips first, keeping it close to the body throughout",
  "cross-body-hammer-curl": "A unilateral dumbbell curl variation where the weight is curled diagonally across the body toward the opposite shoulder, keeping a neutral grip throughout. This angle change places extra emphasis on the brachialis and brachioradialis while still working the biceps.\n\n- Start with the dumbbell at your side, palm facing your body\n- Curl the weight up and across toward the opposite shoulder, not straight up\n- Keep the elbow anchored near your side rather than drifting forward\n- Control the descent back to the starting position on the same diagonal path\n- Work one arm fully before switching to avoid uneven momentum",
  "crunch": "A classic bodyweight ab exercise that flexes the spine through a short range of motion, targeting the rectus abdominis without much involvement of the hip flexors. It's commonly used as a foundational core exercise for building trunk control.\n\n- Lie on the back with knees bent and feet flat on the floor\n- Place hands lightly behind the head or crossed on the chest\n- Curl the shoulders and upper back off the floor by flexing the spine\n- Keep the lower back pressed into the floor throughout\n- Avoid pulling on the neck or using momentum to lift the torso",
  "curtsy-lunge": "The curtsy lunge involves stepping one leg diagonally behind and across the body, targeting the glutes with quad assistance while also challenging hip stability in a rotational plane. It's commonly used to add variety to lower-body training and to hit the glutes from a different angle.\n\n- Stand with feet hip-width apart and step one leg diagonally behind the other into a crossing position\n- Lower until the back knee approaches the floor beside the front foot\n- Keep the front knee tracking over the toes and the hips facing forward\n- Maintain an upright torso rather than leaning forward into the movement\n- Push through the front foot to return to the starting stance",
  "dead-bug": "A floor-based core exercise where you move opposite arm and leg while keeping the low back pressed into the ground, training control of the spine under limb movement. It's often used to build the ability to brace the abs while the limbs are in motion.\n\n- Lie on your back with arms reaching toward the ceiling and knees bent 90 degrees over the hips\n- Press the lower back flat into the floor and keep it there throughout\n- Slowly extend one arm overhead and the opposite leg straight, stopping just above the floor\n- Return to start with control and alternate sides without letting the back arch\n- Move slowly and breathe steadily rather than rushing the reps",
  "decline-barbell-bench-press": "A pressing variation done on a bench angled downward at the head end, targeting the lower portion of the chest while reducing shoulder involvement compared to flat or incline pressing. It's used to add variety and hit the pectorals from a different angle.\n\n- Secure the legs or feet under the pads or footrest before starting\n- Keep the shoulder blades retracted and the chest up throughout the set\n- Lower the bar to the lower-chest area with control, avoiding a fast drop\n- Press the bar back up in a straight line over the chest, locking out the elbows without hyperextending\n- Keep a spotter or safety setup handy since the decline position can make racking the bar awkward",
  "decline-dumbbell-press": "A pressing movement performed on a decline bench with dumbbells, emphasizing the lower chest while reducing shoulder involvement compared to flat or incline pressing. Feet are secured under pads while the torso is angled downward.\n\n- Secure legs under the bench pads and lie back on the decline bench\n- Hold dumbbells above the lower chest with palms facing forward or slightly angled\n- Lower the dumbbells under control to the sides of the lower chest\n- Press back up in a controlled path without letting the dumbbells drift toward the face\n- Keep the core braced and avoid rocking the torso during the press",
  "decline-sit-up": "A sit-up performed on a decline bench, which increases the range of motion and resistance by adding a downward angle to the torso. It intensifies the demand on the abs and hip flexors compared to a flat sit-up.\n\n- Secure feet under the pads or bar at the top of the decline bench\n- Lower the torso back until it's in line with the bench, keeping control\n- Curl the spine to sit back up, leading with the chest rather than the head\n- Keep the movement continuous without bouncing at the bottom\n- Brace the abs throughout rather than relying on hip flexor swing",
  "deficit-deadlift": "A deadlift performed while standing on a raised platform, increasing the range of motion and demanding greater hip and hamstring involvement off the floor. This variation builds pulling strength through a deeper starting position and challenges positioning at the bottom of the lift.\n\n- Stand on a stable platform of a few inches, with the bar over midfoot\n- Hinge down to grip the bar, keeping shins close and hips lower than in a standard deadlift\n- Brace the core and pull the slack out of the bar before initiating the pull\n- Drive through the floor, keeping the bar path close to the body as it passes the knees\n- Lock out by extending the hips fully without leaning back excessively",
  "deficit-push-up": "A push-up variation performed with hands elevated on blocks, handles, or plates, allowing the chest to travel below hand level for a greater range of motion. This increased stretch places more demand on the chest and triceps compared to a standard push-up.\n\n- Use two stable, even-height platforms positioned under each hand\n- Keep the body in a straight line and core braced throughout the descent\n- Lower the chest below the level of the hands, feeling a deeper stretch across the pecs\n- Press back up to full elbow extension without letting the hips sag\n- Control the descent rather than dropping quickly into the bottom position",
  "deficit-reverse-lunge": "This unilateral lunge variation is performed by standing on a raised platform and stepping back into a reverse lunge, allowing for a greater range of motion at the hip and knee than a standard lunge. It builds single-leg strength and control while emphasizing the glutes of the working leg, with the quads assisting.\n\n- Stand on a box or plate with dumbbells at your sides, then step one foot back and down toward the floor\n- Lower until the back knee approaches the ground and the front thigh is close to parallel\n- Keep the front shin roughly vertical and weight through the front heel and midfoot\n- Drive through the front leg to return to the starting platform without pushing off the trailing foot\n- Keep the torso upright and core braced throughout the descent",
  "diamond-push-up": "A push-up variation performed with the hands close together under the chest, forming a diamond or triangle shape with the thumbs and index fingers. This narrow hand position shifts more emphasis onto the triceps while still engaging the chest.\n\n- Place hands together under the chest with thumbs and index fingers touching\n- Keep elbows tracking close to the body rather than flaring outward\n- Lower the chest toward the hands while maintaining a straight body line\n- Press back up to full extension, squeezing the triceps at the top\n- Keep the core and glutes braced to prevent the hips from sagging",
  "donkey-calf-raise": "A calf raise variation performed on a donkey calf machine with the torso bent forward and hips positioned behind the ankles, which changes the angle of pull on the gastrocnemius compared to standing raises. This position allows a long stretch and strong contraction through the calf.\n\n- Position the balls of the feet on the platform with heels free to drop\n- Keep the hips braced against the pad and torso stable throughout\n- Lower the heels for a full stretch before pressing back up onto the toes\n- Drive through the forefoot and squeeze at the top of the movement\n- Avoid rocking the hips or using body momentum to move the weight",
  "drag-curl": "A barbell curl variation where the bar is dragged straight up along the torso rather than arcing away from the body, keeping the elbows traveling backward instead of forward. This path shifts more of the work onto the biceps by removing front-deltoid assistance common in standard curls.\n\n- Start with the bar against your thighs, gripping shoulder-width\n- Drag the bar up your torso by driving the elbows backward rather than curling forward\n- Keep the bar in contact with or very close to your body throughout the movement\n- Finish with elbows pointing behind you and the bar near chest height\n- Lower back down along the same path, resisting the urge to let the bar swing forward",
  "dragon-flag": "An advanced bodyweight core exercise where the body is lowered and raised as a rigid unit from the shoulders down, pivoting only at the upper back while everything else stays straight. It heavily trains the abs and lower back to resist bending under load.\n\n- Lie on a bench and grip behind your head for anchoring\n- Raise your legs and hips until the body forms a straight line supported only on the upper back and shoulders\n- Keep the entire body rigid from shoulders to feet as you slowly lower toward the bench\n- Stop just before the hips touch and reverse back to the top without letting the lower back sag\n- Control the descent rather than dropping; regress with bent knees or a smaller range if full extension isn't controlled",
  "dumbbell-bench-press": "A horizontal pressing movement using a dumbbell in each hand, allowing a greater range of motion and independent arm movement compared to a barbell. It builds the chest, front shoulders, and triceps while also demanding stabilization through the shoulder joint.\n\n- Lie on a flat bench with dumbbells held above the chest, palms facing forward\n- Lower the dumbbells under control until upper arms are roughly parallel to the floor or slightly below\n- Press the dumbbells up and slightly inward until arms are extended without clanking them together\n- Keep shoulder blades retracted and feet planted for a stable base\n- Avoid letting the elbows flare excessively or the dumbbells drift out of a controlled path",
  "dumbbell-curl": "A biceps isolation exercise performed by curling a dumbbell in each hand, allowing independent arm movement and the option to rotate the wrist through the range of motion. It also engages the forearms as stabilizers and gripping muscles.\n\n- Stand with dumbbells at your sides, palms facing forward or neutral to start\n- Keep elbows tucked close to the body throughout\n- Curl the weights up while rotating to a palms-up position if using a supinating curl\n- Avoid swinging the shoulders or using body momentum\n- Lower under control back to the starting position",
  "dumbbell-floor-press": "A floor-based pressing variation using dumbbells, where the upper arms stop against the floor to limit range of motion and emphasize the triceps and lockout strength. The independent dumbbell movement also demands shoulder stability.\n\n- Lie on the floor with knees bent, feet flat, holding a dumbbell in each hand\n- Lower the dumbbells until the upper arms rest lightly on the floor\n- Pause briefly at the bottom without relaxing the shoulders or bouncing\n- Press the dumbbells back up until arms are extended, keeping wrists stacked over elbows\n- Avoid letting the elbows flare wide or the dumbbells drift out of line",
  "dumbbell-fly": "A chest isolation exercise performed lying on a flat bench, using a wide arcing motion of the arms to stretch and contract the pecs without significant elbow flexion changes. It targets the chest with some involvement of the front delts as stabilizers of the shoulder joint.\n\n- Lie flat on the bench with feet planted and shoulder blades set\n- Start with dumbbells above the chest, palms facing each other, elbows slightly bent\n- Lower the weights out to the sides in a wide arc until you feel a stretch across the chest\n- Bring the dumbbells back together over the chest by squeezing the pecs, not by pressing\n- Keep a slight, consistent bend in the elbows throughout to avoid stress on the joint",
  "dumbbell-lateral-raise": "An isolation exercise where dumbbells are raised out to the sides to shoulder height, primarily targeting the side delts to build shoulder width and the rounded look of the deltoid. It's a staple accessory movement for shoulder development that also lightly engages the traps.\n\n- Stand with a dumbbell in each hand at your sides, torso upright, and a slight bend in the elbows\n- Raise the arms out to the sides until roughly shoulder height, leading with the elbows rather than the hands\n- Avoid using momentum by swinging the torso or shrugging the traps to lift the weight\n- Keep a slight forward tilt of the pinky or a neutral wrist rather than rotating the dumbbell dramatically\n- Lower the dumbbells slowly back to your sides rather than dropping them",
  "dumbbell-overhead-triceps-extension": "An isolation exercise performed standing or seated, pressing a single dumbbell or two dumbbells overhead and lowering it behind the head to stretch and work the triceps, particularly the long head. It's commonly used to build arm size and overhead extension strength.\n\n- Hold the dumbbell overhead with both hands cupped under the top end, or one dumbbell per arm\n- Keep upper arms close to the ears and elbows pointing forward\n- Lower the weight behind the head by bending only at the elbows\n- Extend back to full overhead lockout without swinging the torso\n- Brace the core to avoid arching the lower back during the movement",
  "dumbbell-pullover": "A supine isolation exercise performed lying across a bench, lowering a single dumbbell behind the head and pulling it back over the chest. It stretches and works the lats while also engaging the chest and rib cage area.\n\n- Lie with only the upper back on the bench, hips low and feet planted\n- Hold the dumbbell with both hands cupped under the top plate\n- Lower the dumbbell behind the head with a slight elbow bend, feeling a stretch\n- Pull the weight back over the chest by driving through the lats\n- Keep the arc controlled rather than swinging the weight up",
  "dumbbell-rear-delt-fly": "A bent-over isolation exercise that raises dumbbells out to the sides to target the rear deltoids and upper back muscles. It's typically performed hinged forward at the hips with a slight bend in the knees for stability.\n\n- Hinge forward at the hips with a flat back and soft knees, dumbbells hanging below the chest\n- Raise the arms out to the sides in an arcing motion, leading with the elbows\n- Squeeze the shoulder blades together at the top of the movement\n- Keep a slight bend in the elbows throughout rather than locking them out\n- Lower slowly and avoid using momentum or torso swing to lift the weight",
  "dumbbell-romanian-deadlift": "A hip-hinge movement performed holding a pair of dumbbells in front of the thighs, targeting the hamstrings and glutes through a controlled stretch under load. It's a common accessory for building posterior chain strength and improving hip hinge mechanics without the loading demands of a barbell deadlift.\n\n- Start standing tall with dumbbells resting against your thighs, feet hip-width apart\n- Push your hips back while keeping a soft bend in the knees and a flat back\n- Lower the dumbbells along your legs until you feel a stretch in the hamstrings, then reverse the motion\n- Keep the dumbbells close to your body throughout the descent and ascent\n- Drive your hips forward to stand tall, squeezing the glutes at the top",
  "dumbbell-row": "A unilateral horizontal pull performed one arm at a time, typically bracing the opposite hand on a bench, allowing a deep range of motion and focused work on each side of the lats and upper back. Training one side at a time helps address side-to-side strength imbalances and lets you isolate the pulling arm.\n\n- Brace one knee and hand on a bench with a flat back and neutral neck\n- Let the dumbbell hang fully at arm's length to get a complete stretch at the bottom\n- Pull the elbow back and up along the side of the torso, not out to the side\n- Squeeze the shoulder blade back at the top before lowering under control\n- Keep the torso still and avoid rotating the hips or spine to help lift the weight",
  "dumbbell-shrug": "A trap isolation exercise done by holding a dumbbell in each hand and lifting the shoulders vertically, allowing a more natural arm path and slightly greater range of motion than a barbell version. It also builds grip and forearm endurance.\n\n- Hold dumbbells at your sides with arms straight and shoulders relaxed\n- Lift the shoulders straight up toward the ears, avoiding forward or backward rolling\n- Keep elbows soft but not bent to shift work to the arms\n- Squeeze at the top before lowering slowly\n- Maintain an upright posture without leaning back for momentum",
  "dumbbell-skull-crusher": "Similar to the barbell version, this triceps isolation exercise uses dumbbells lying on a bench, allowing each arm to move independently and often permitting a neutral or rotating grip. It builds triceps mass and elbow extension strength.\n\n- Lie flat on a bench holding dumbbells straight above the shoulders\n- Keep elbows fixed in place and pointed up throughout the set\n- Lower the dumbbells toward the sides of the head with control\n- Extend the arms back to the top without letting elbows drift outward\n- Keep wrists stable and avoid banging the dumbbells together at the top",
  "ez-bar-curl": "A biceps curl performed with a cambered EZ-bar, whose angled grips reduce wrist strain compared to a straight bar while still heavily loading the biceps and forearms. It's a common alternative for lifters who find a straight bar uncomfortable on the wrists.\n\n- Grip the bar on the angled sections at a comfortable width\n- Keep elbows close to the torso and stationary\n- Curl the bar upward using elbow flexion, not shoulder or back movement\n- Squeeze the biceps at the top of the rep\n- Lower with control to full elbow extension",
  "ez-bar-skull-crusher": "A barbell isolation exercise performed lying on a bench, lowering the bar toward the forehead by bending only at the elbows. The EZ-bar's angled grip reduces wrist strain while still heavily loading the triceps through a long range of motion.\n\n- Lie on a flat bench with arms extended straight above the shoulders\n- Keep upper arms vertical and elbows pointed toward the ceiling, not flared\n- Lower the bar toward the forehead or just behind it by bending the elbows\n- Press back up by extending the elbows without moving the shoulders\n- Use a controlled tempo to avoid the bar dropping too fast",
  "face-pull": "A cable exercise pulling a rope attachment toward the face at roughly eye or forehead height, targeting the rear delts, upper back, and traps. It's widely used to build shoulder health and posture-supporting pull strength.\n\n- Set the cable pulley to upper chest or head height and use a rope attachment\n- Pull the rope toward the face, splitting the ends apart as the hands approach the head\n- Lead the pull with the elbows high, keeping them above shoulder height\n- Squeeze the shoulder blades together and pause briefly at the end range\n- Control the return to full arm extension without letting the shoulders round forward",
  "farmers-walk": "A loaded carry performed by walking for distance or time while holding a heavy dumbbell in each hand at your sides, building grip endurance, trap and shoulder stability, and overall total-body bracing. It's a simple but demanding test of grip and posture under load.\n\n- Pick up a dumbbell in each hand with a firm grip and stand tall\n- Keep the shoulders back and down, chest up, and core braced\n- Walk with controlled, even steps, avoiding excessive leaning to either side\n- Keep the arms straight and let the weights hang naturally without swinging\n- Set the weights down under control at the end rather than dropping them",
  "floor-press": "A bench press variation performed lying on the floor, which shortens the range of motion by stopping the upper arm at the floor rather than letting the shoulder stretch further. This shifts more emphasis onto the triceps and lockout strength while reducing shoulder strain from the bottom position.\n\n- Lie on the floor with knees bent and feet flat, barbell set up on blocks, rack, or handed off by a spotter\n- Lower the bar under control until your upper arms touch the floor, then pause briefly\n- Drive the bar back up by extending the elbows, keeping wrists stacked over them\n- Keep shoulder blades pulled back and down throughout the press\n- Avoid bouncing the arms off the floor to generate momentum",
  "forward-lunge": "A unilateral lunge performed by stepping forward from a standing position and lowering into a lunge, targeting the quads with secondary glute involvement while training single-leg stability. Dumbbells held at the sides add resistance to the pattern.\n\n- Hold dumbbells at your sides with shoulders back and torso upright\n- Step forward into a stance long enough that the front knee stays over the ankle at the bottom\n- Lower the back knee toward the floor under control without letting the front knee drift past the toes\n- Push back through the front foot to return to the starting position\n- Keep movements controlled rather than lunging with momentum",
  "frog-pump": "A bodyweight glute isolation exercise performed lying on the back with the soles of the feet together, driving the hips upward to emphasize glute contraction through a short range of motion. It's often used as a warm-up or finisher for glute activation.\n\n- Lie on your back with knees bent and soles of the feet pressed together, knees falling open\n- Drive the hips upward by squeezing the glutes, keeping the feet in contact\n- Pause and squeeze hard at the top of the movement\n- Lower the hips under control without fully resting between reps\n- Keep the lower back neutral and avoid overarching at the top",
  "front-raise": "A shoulder isolation movement that lifts a dumbbell in each hand out in front of the body to target the anterior deltoids. It's commonly used to add direct front-delt work after pressing movements.\n\n- Stand tall with dumbbells in front of the thighs, palms facing down or neutral\n- Raise one or both arms straight in front to roughly shoulder height\n- Keep a slight bend in the elbows and avoid using momentum\n- Lower under control back to the start\n- Brace the core to prevent leaning back as the weight rises",
  "front-squat": "A squat performed with the barbell racked across the front of the shoulders, demanding an upright torso and strong core bracing. It emphasizes the quads more directly than back squat variations while also challenging the abs and upper back to keep the bar supported.\n\n- Rest the bar on the front deltoids with elbows lifted high, using a clean grip or crossed-arm grip\n- Keep the torso as vertical as possible throughout the movement\n- Brace the core hard to resist the bar pulling you forward\n- Sit straight down between the hips and knees to full depth\n- Drive up while keeping the elbows high and chest tall",
  "glute-bridge": "A floor-based hinge exercise performed lying on your back with a barbell across the hips, driving the hips up into extension. It's a foundational movement for building glute strength and is often used as a stepping stone toward the hip thrust.\n\n- Lie on your back with knees bent, feet flat, and the barbell resting across your hips\n- Brace your core and drive through your heels to lift your hips off the floor\n- Extend your hips fully, squeezing the glutes at the top of the movement\n- Keep your ribs down and avoid excessive arching in the lower back\n- Lower your hips back down under control without dropping the weight",
  "glute-ham-raise": "A bodyweight compound hinge exercise performed on a GHD or footplate that trains the hamstrings, glutes, and lower back through a large range of motion combining hip and knee extension. It builds both concentric and eccentric hamstring strength.\n\n- Position the footplate and pad so the knees can bend and extend freely\n- Lower the torso forward under control, keeping the hips extended\n- Drive back up primarily by curling the legs and extending the hips together\n- Keep the core braced to prevent the lower back from rounding\n- Adjust range of motion or assistance as needed to maintain smooth control",
  "goblet-squat": "A squat performed while holding a single dumbbell vertically at chest height, making it an accessible entry point for learning proper squat mechanics. It trains the quads and glutes while the front-loaded position naturally encourages an upright torso and good depth.\n\n- Hold the dumbbell close to the chest with both hands cupping one end\n- Stand with feet slightly wider than shoulder width, toes turned slightly out\n- Sit down between the legs, keeping elbows brushing the inside of the knees at the bottom\n- Keep the chest up and back flat throughout the movement\n- Drive through the feet to stand while keeping the dumbbell close to the body",
  "good-morning": "A barbell hinge exercise performed with the bar racked across the upper back, bending forward at the hips to load the hamstrings, glutes, and lower back. It reinforces hip hinge mechanics and posterior chain strength in a standing, loaded position.\n\n- Set the bar on the upper traps as in a low-bar squat position\n- Stand with feet shoulder-width apart and a slight bend in the knees\n- Hinge at the hips, pushing them back while keeping the spine neutral\n- Lower your torso until it's near parallel to the floor or as flexibility allows\n- Drive the hips forward to return to standing, keeping the bar path stable",
  "hack-squat": "A machine-based squat performed on an angled sled, with the back and shoulders pressed against a pad while the feet push a platform. It heavily loads the quads through a fixed path of motion, allowing you to squat deep with less demand on balance and core stabilization than a free squat.\n\n- Set foot placement mid-to-low on the platform for more quad emphasis, or higher for more glute involvement\n- Keep your lower back flat against the pad throughout the movement\n- Lower until thighs approach parallel or slightly below, without letting the knees cave inward\n- Drive through the whole foot, avoiding excessive weight shifting onto the toes\n- Control the descent rather than letting the sled drop",
  "hammer-curl": "A dumbbell elbow flexion exercise performed with a neutral, palms-facing-in grip, targeting the biceps along with the brachialis and forearm muscles. The neutral grip shifts emphasis slightly away from the biceps peak and onto the outer arm, making it a solid complement to standard curls.\n\n- Stand tall with dumbbells at your sides, palms facing your torso throughout the lift\n- Keep elbows pinned close to your ribs and curl by bending only at the elbow\n- Raise the dumbbells to shoulder height without swinging the torso or shrugging\n- Lower under control through the full range before starting the next rep\n- Avoid using momentum or leaning back to heave the weight up",
  "hammer-strength-chest-press": "A plate-loaded, independent-arm pressing machine that trains the chest through a horizontal push pattern while also working the triceps. The unilateral handle design allows each side to move freely, which can help address strength imbalances between arms.\n\n- Adjust the seat so handles start at mid-chest level\n- Press both handles forward evenly, extending the arms without slamming the elbows straight\n- Keep the back flat against the pad and feet planted throughout the set\n- Lower the handles slowly until the chest feels a stretch before pressing again\n- Drive through a consistent tempo rather than jerking the weight off the start position",
  "handstand-push-up": "An advanced bodyweight pressing exercise performed upside down against a wall, requiring significant front delt and triceps strength along with balance and body control. It's essentially an overhead press using bodyweight as resistance in an inverted position.\n\n- Kick up into a handstand against a wall with hands shoulder-width apart and fingers spread for stability\n- Lower yourself by bending the elbows until the head lightly approaches the floor\n- Keep the core and glutes tight to maintain a straight, stacked line from wrists through hips\n- Press back up by extending the elbows fully, keeping the body controlled rather than kicking off the wall\n- Control the tempo on the way down rather than dropping quickly",
  "hang-clean": "A variation of the clean started from a hanging position above the knees rather than the floor, emphasizing the explosive hip extension and pull-under phases of the lift. It trains full-body power with a greater focus on speed and timing than the pull from the ground.\n\n- Start standing with the bar hanging at mid-thigh or just above the knee, hips hinged back slightly\n- Keep the back flat and shoulders slightly ahead of the bar in the starting position\n- Explosively extend the hips, knees, and ankles to drive the bar upward\n- Pull yourself under the bar quickly, catching it in a front-rack quarter-squat position\n- Stand tall to finish, keeping the elbows up and the bar secure on the shoulders",
  "hang-snatch": "A snatch performed starting from a hang position, usually around or above the knee, instead of the floor, which removes the initial pull and emphasizes the explosive second pull and turnover. It develops hip power, timing, and overhead catching ability with a shorter, more controlled setup.\n\n- Begin standing tall with the bar in hand, then lower it to the chosen hang position by hinging at the hips with a flat back\n- Keep the bar close to the thighs as you initiate the pull\n- Explosively extend the hips, knees, and ankles while shrugging the shoulders\n- Pull under the bar quickly and receive it overhead in a stable, shallow squat\n- Maintain a tight core and vertical torso through the catch to avoid drifting forward or back",
  "hanging-knee-raise": "A regression of the hanging leg raise that bends the knees to reduce leverage, making it a more accessible way to target the lower abs from a dead hang. It still challenges grip and shoulder stability while keeping tension on the core.\n\n- Hang from the bar with arms straight and shoulders engaged\n- Drive knees up toward the chest by curling the pelvis, not just swinging the legs\n- Pause briefly at the top before lowering with control\n- Avoid using momentum or kipping the body to move the weight\n- Keep the ribcage drawn down to prevent lower back arching",
  "hanging-leg-raise": "A demanding hanging core exercise performed from a pull-up bar, raising the straight legs up toward the torso to build lower ab and hip flexor strength while challenging grip and shoulder stability. It also recruits the obliques to keep the body from swinging.\n\n- Hang from the bar with a shoulder-width grip and arms fully extended\n- Brace the core and posteriorly tilt the pelvis before the legs move\n- Raise straight legs until roughly parallel to the floor or higher, avoiding momentum\n- Lower under control without letting the body swing\n- Keep shoulders active and avoid excessive arching in the lower back",
  "high-bar-back-squat": "A back squat variation with the bar resting high on the traps, allowing a more upright torso and greater knee travel forward. This positioning shifts more emphasis onto the quads while still involving the glutes, and is common in Olympic-style and general strength training.\n\n- Rest the bar directly on top of the traps, not lower on the rear delts\n- Keep the torso relatively upright throughout the descent\n- Allow the knees to travel forward over the toes as you sit down\n- Descend to full depth with hips dropping below knee level if mobility allows\n- Drive the knees out and push through mid-foot to stand",
  "high-to-low-cable-fly": "A cable fly variation with the pulleys set high, pulling the handles downward and across the body to emphasize the lower portion of the chest. This diagonal path isolates the pecs while keeping constant tension through the range of motion.\n\n- Set both pulleys above shoulder height and stand centered between the towers\n- Start with arms extended up and out to the sides, elbows slightly bent\n- Pull the handles down and together in front of the lower chest or hips\n- Squeeze the chest at the bottom of the movement before returning slowly\n- Keep the torso upright and avoid leaning or jerking the weight downward",
  "hip-abduction-machine": "A seated machine exercise that isolates the hip abductors, with the glutes assisting, by pushing the legs outward against resistance pads. It's commonly used to target the outer hip and glute medius region.\n\n- Sit back fully in the seat with knees against the pads and back supported\n- Push the legs outward in a controlled arc to full range without jerking\n- Pause briefly at the outer position before returning\n- Control the return so the pads don't slam back together\n- Keep the torso still and avoid using the hands to assist the movement",
  "hip-adduction-machine": "A seated machine exercise that isolates the adductors by drawing the legs inward against resistance pads. It's used to build strength through the inner thigh musculature.\n\n- Sit with back supported and knees positioned against the outer pads\n- Squeeze the legs together in a controlled motion through the full range\n- Pause briefly at the inward position before allowing the legs to return\n- Resist the pads on the way back out rather than letting them snap open\n- Keep hips and torso stable throughout the movement",
  "hip-thrust": "A glute-focused hinge exercise performed with the upper back braced against a bench and a barbell across the hips, driving the hips upward into extension. It's one of the most direct ways to load and build the glutes through a full range of hip extension.\n\n- Position your upper back on a bench with the barbell rolled over your hips, feet flat and shins roughly vertical at the top\n- Brace your core and drive through your heels to lift your hips upward\n- Squeeze your glutes hard at the top, forming a straight line from shoulders to knees\n- Avoid overextending the lower back at lockout\n- Lower under control back to the starting position without resting the hips on the floor between reps",
  "incline-barbell-bench-press": "Performed on an angled bench set between roughly 15 and 45 degrees, this press shifts emphasis toward the upper chest and front shoulders while still training the triceps. It's a compound lift used to build a fuller, more balanced chest.\n\n- Set the bench incline moderately; too steep turns the lift into a shoulder press\n- Retract and depress the shoulder blades against the pad before lowering the bar\n- Lower the bar to the upper chest or collarbone area, not the neck\n- Keep the elbows tucked slightly rather than flared to protect shoulder positioning\n- Press up and slightly back in line with the shoulder joint, finishing with arms extended",
  "incline-dumbbell-curl": "A biceps isolation variation performed while seated on an incline bench, which places the arms behind the body and increases the stretch on the biceps at the bottom of the movement. This position also limits the ability to cheat with body momentum.\n\n- Sit back firmly against an incline bench with arms hanging straight down\n- Let the arms fully extend to get a deep stretch at the bottom\n- Curl the dumbbells up while keeping the upper arms stationary\n- Avoid letting the elbows drift forward as the weight rises\n- Lower slowly back to a full stretch each rep",
  "incline-dumbbell-fly": "This variation of the fly is performed on an incline bench, shifting emphasis toward the upper portion of the chest while still involving the front delts as stabilizers. The incline angle changes the line of pull so the stretch and contraction are felt more in the clavicular head of the pec.\n\n- Set the bench to a moderate incline, around 30-45 degrees\n- Begin with dumbbells over the upper chest, palms facing in and elbows slightly bent\n- Lower the arms out wide until a stretch is felt across the upper chest\n- Bring the dumbbells back together in an arcing path, leading with the elbows\n- Avoid arching the lower back off the bench to compensate for a steep incline",
  "incline-dumbbell-press": "A pressing exercise performed on an inclined bench with dumbbells, targeting the upper portion of the chest along with the front delts and triceps. The incline angle shifts more load onto the clavicular head of the chest compared to flat pressing.\n\n- Set the bench to a moderate incline, typically 30-45 degrees\n- Start with dumbbells at shoulder level, elbows under wrists\n- Press the dumbbells up and slightly together without locking out aggressively\n- Lower with control back to shoulder level, feeling a stretch across the upper chest\n- Keep the lower back flat against the bench and avoid excessive arching",
  "incline-machine-press": "A guided horizontal pressing movement performed on a machine with an angled seat and handles, targeting the upper chest along with the front delts and triceps. The fixed path makes it a good option for building pressing strength and volume without needing a spotter.\n\n- Set the seat height so handles align with the upper chest\n- Press the handles up and slightly forward until arms are extended without locking out hard\n- Keep shoulder blades pulled back and down against the pad throughout\n- Lower the weight under control until a stretch is felt across the chest\n- Avoid flaring elbows to a full 90 degrees to keep tension off the shoulder joint",
  "inverted-row": "A bodyweight horizontal pull performed under a bar or on rings, where the body is held rigid and pulled up toward a fixed anchor point. It builds upper back and lat strength while also engaging the biceps and core to keep the body straight.\n\n- Set the bar height so the body forms a straight line from head to heels\n- Pull the chest toward the bar, driving elbows back and squeezing the shoulder blades\n- Keep hips up and body rigid, avoiding sagging or piking\n- Lower under control to full arm extension\n- Adjust foot position or bar height to change difficulty",
  "jm-press": "A hybrid barbell press that blends a close-grip bench press with a skull crusher, targeting the triceps heavily while also involving the chest. The bar is lowered toward the neck or upper chest with the elbows tucked, making it a strong triceps-building compound movement.\n\n- Lie on a bench with a grip slightly narrower than shoulder width\n- Lower the bar toward your neck or chin, letting elbows travel forward and down\n- Keep elbows tucked close to the body rather than flaring\n- Drive the bar back up through a combination of elbow and shoulder extension\n- Move deliberately since the bar path is close to the face",
  "jump-squat": "A bodyweight squat performed with an explosive jump at the top of the movement, used to develop lower-body power and rate of force development through the quads and calves. It combines squat mechanics with a plyometric finish for athletic power training.\n\n- Stand with feet shoulder-width apart and descend into a squat with control\n- Drive explosively upward through the heels and midfoot to leave the ground\n- Extend the ankles fully at the top for maximum height\n- Land softly with bent knees, absorbing impact before the next rep\n- Keep the chest up and core braced throughout the movement",
  "kettlebell-swing": "An explosive hip-hinge movement where a kettlebell is driven forward and up using force generated from the hips, training power output through the glutes and hamstrings. The arms act as a guide rope, transferring the momentum created by the hips rather than lifting the weight.\n\n- Hinge back with the kettlebell between the legs, keeping the spine neutral\n- Snap the hips forward forcefully to project the kettlebell to chest height\n- Keep arms relaxed and let the hip drive create the movement, not the shoulders\n- Squeeze the glutes hard at the top of each rep\n- Maintain a braced core throughout to protect the lower back during the fast tempo",
  "kneeling-cable-pulldown": "A pulldown variation performed kneeling in front of a high cable pulley, which fixes the hips and removes the ability to lean back for momentum. This position keeps tension more strictly on the lats throughout the pull.\n\n- Kneel upright with hips stacked over knees and core braced\n- Reach up to grip the bar or handles with arms extended\n- Pull down by driving elbows toward the floor, not just bending arms\n- Keep the torso still, resisting the urge to rock backward\n- Extend fully at the top and repeat with a steady tempo",
  "kroc-row": "A heavy, high-rep unilateral dumbbell row named after Janet Kroc, using a bit of body English and momentum to move loads beyond what a strict dumbbell row would allow, building grip, lat, and upper back strength and work capacity. It trades some strictness for load and volume, making it a tool for building raw pulling strength rather than pure isolation.\n\n- Brace with one hand on a support and stagger the stance for stability\n- Allow a slight hip and torso rotation to help initiate heavier reps\n- Pull the elbow back aggressively while keeping the shoulder from rounding forward excessively\n- Maintain a strong grip on the dumbbell throughout the higher rep ranges typically used\n- Control the lowering phase even though the pull itself uses some momentum",
  "l-sit": "A static bodyweight hold where the legs are extended in front of the body while supported on the hands, demanding significant abdominal and hip flexor strength along with shoulder stability. It's a benchmark core and body-tension exercise used in gymnastics-style training.\n\n- Support your body on parallettes, blocks, or the floor with arms straight and shoulders pressed down away from the ears\n- Lift the legs straight out in front, keeping knees locked and toes pointed\n- Keep the chest slightly lifted and the low back from rounding excessively\n- Hold the position for time, breathing normally instead of holding your breath\n- Regress by bending one or both knees if a full straight-leg hold isn't yet possible",
  "landmine-press": "A single-arm pressing movement using one end of a barbell anchored in a landmine attachment, driving the weight up and slightly across the body along a natural arc. It trains the front delts, chest, and triceps while being easier on the shoulder joint than a straight overhead press due to the angled path.\n\n- Stand in a staggered or split stance holding the barbell end at shoulder height with one hand\n- Press the bar up and slightly forward along its natural diagonal path\n- Brace the core to prevent excessive twisting through the trunk as you press\n- Keep the shoulder blade moving naturally with the arm rather than staying pinned back\n- Lower the bar back to shoulder height under control before the next rep",
  "landmine-row": "A horizontal pull using a barbell anchored in a landmine attachment, pulled with one or both hands using a neutral grip, which is friendly on the shoulders while building upper back and lat thickness. The fixed arc of the bar provides a stable, guided path that's useful for heavier pulling with less technical demand than a free barbell.\n\n- Anchor the bar and straddle it or stand to the side depending on the attachment\n- Hinge at the hips with a flat back and grip the sleeve with a neutral hand position\n- Pull the bar toward the torso, driving elbows back and keeping them close to the body\n- Squeeze the shoulder blades together at the top of the movement\n- Lower under control to a full stretch without letting the back round",
  "landmine-twist": "A rotational exercise using a barbell anchored in a landmine unit, swept side to side to train the obliques and rotational core strength under load. The angled bar path makes it accessible while still providing significant resistance.\n\n- Hold the end of the barbell with both hands extended in front of the chest\n- Brace the core and rotate the bar down toward one hip, pivoting through the trunk\n- Keep arms relatively fixed so the movement comes from rotating the torso and hips\n- Control the bar back through center and continue to the opposite side\n- Avoid letting the lower back round or the hips sway excessively",
  "larsen-press": "A bench press variation performed with the feet up off the floor or resting flat on the bench, removing leg drive and arch from the lift. This isolates the upper body pressing muscles and demands strict, controlled technique.\n\n- Lie on the bench with feet raised off the floor or flat on the bench surface, hips down\n- Keep the lower back naturally flat against the bench without driving through the legs\n- Lower the bar under control to the chest, keeping elbows at a moderate angle to the torso\n- Press the bar back up in a straight line, relying purely on upper body strength\n- Avoid letting the hips rise or the body shift to compensate for the lack of leg drive",
  "lat-pulldown": "A cable-based vertical pull performed seated at a pulldown station, pulling a bar down toward the upper chest. It's a scalable alternative to pull-ups that trains the lats with biceps and upper back assistance.\n\n- Sit tall with thighs secured under the pad and chest up\n- Grip the bar slightly wider than shoulder width\n- Initiate the pull by depressing the shoulder blades before bending the elbows\n- Bring the bar to the upper chest while keeping the torso mostly upright\n- Extend arms fully and let the shoulder blades stretch at the top before the next rep",
  "lateral-lunge": "Also known as a side lunge, this movement takes a leg out to the side while the other stays extended, loading the adductors of the working leg along with the quads and glutes. It trains strength and mobility in the frontal plane, which is often underworked compared to forward and backward movement.\n\n- Take a wide step to the side and sit the hips back and down over the bending leg\n- Keep the straight leg extended with the foot flat, feeling a stretch through the inner thigh\n- Keep the chest up and the bending knee tracking over the toes\n- Push through the heel of the working leg to return to standing\n- Keep the movement controlled rather than dropping quickly into the bottom position",
  "leaning-cable-lateral-raise": "A unilateral cable raise performed while leaning away from the pulley, which increases the range of motion and places greater stretch tension on the side delt at the bottom of the movement. This variation is popular for maximizing shoulder width development.\n\n- Hold onto an upright or the machine frame with one hand and lean your torso away from the low pulley\n- Let the working arm hang down across the body slightly to start, feeling a stretch in the side delt\n- Raise the arm out and up to shoulder height, leading with the elbow\n- Keep the lean stable throughout rather than using body swing to assist the lift\n- Lower back down slowly to the stretched starting position before the next rep",
  "leg-extension": "A machine isolation exercise that extends the knees against resistance to target the quadriceps directly, commonly used to build quad size and strength without involving the hips. The seated position isolates knee extension from other lower-body muscle groups.\n\n- Adjust the seat so the knees align with the machine's pivot point and the pad rests on the lower shins\n- Extend the legs fully, squeezing the quads at the top\n- Avoid using momentum or jerking the weight up\n- Lower the weight under control back to the starting position\n- Keep the back and hips pressed against the seat throughout the movement",
  "leg-press": "A seated machine exercise where you push a weighted platform away using your legs, built to load the quads, glutes, and hamstrings without requiring the core stabilization needed in a free squat. It's commonly used to build leg size and strength with a controlled, supported range of motion.\n\n- Set foot placement shoulder-width, mid-platform, for balanced quad and glute involvement\n- Keep your lower back pressed into the seat pad throughout the set\n- Lower the platform until your knees approach your chest without your hips rounding off the pad\n- Press through the full foot, avoiding letting the knees cave inward\n- Stop just short of locking the knees out completely at the top",
  "leg-press-calf-raise": "This exercise uses the leg press sled to load calf raises with the legs extended, working the gastrocnemius and soleus through ankle extension against a fixed resistance path. It allows heavy loading in a stable, supported position.\n\n- Place the balls of the feet on the lower edge of the platform with heels hanging off\n- Keep the legs almost straight but avoid locking the knees\n- Push through the toes to extend the ankles fully, then lower under control\n- Let the heels drop below the platform edge to get a full stretch\n- Avoid bending the knees to help the movement, which shifts work off the calves",
  "low-bar-back-squat": "A back squat variation where the bar sits lower across the rear delts, encouraging a more hip-dominant pattern with greater forward torso lean. This position increases involvement of the glutes and hamstrings and often allows heavier loading, making it popular in powerlifting.\n\n- Position the bar across the rear deltoids, below the traps\n- Use a slightly wider grip to create a shelf for the bar\n- Push the hips back first as you initiate the descent, allowing the torso to lean forward\n- Keep the chest up despite the lean to maintain a neutral spine\n- Drive the hips up and forward out of the bottom to stand tall",
  "low-to-high-cable-fly": "A cable fly variation where the pulleys are set low and the handles are brought upward and across the body, emphasizing the upper portion of the chest. It isolates the pecs through a diagonal pressing arc while keeping tension constant.\n\n- Set both pulleys near the floor and stand centered between the towers\n- Start with arms low and slightly behind the body, elbows softly bent\n- Sweep the handles upward and inward until hands meet around upper chest or chin height\n- Squeeze the chest at the top of the arc before returning under control\n- Keep the torso still, avoiding using the legs or back to help lift the weight",
  "lu-raise": "A lateral raise variation performed at an angle in front of the body rather than straight out to the side, targeting the side delts through a longer range of motion while reducing traps involvement. Popularized as a way to keep tension on the shoulder muscle itself, it's done with dumbbells raised toward the front-side diagonal rather than pure abduction.\n\n- Hold light dumbbells and raise them up and slightly forward, roughly 30-45 degrees in front of the torso plane\n- Lead with the elbows, keeping a slight bend throughout\n- Rotate the pinky slightly up at the top to bias the side delt\n- Avoid shrugging the traps to lift the weight\n- Use a controlled tempo rather than swinging the dumbbells up",
  "lying-leg-curl": "A machine isolation exercise performed face-down that curls the ankle pad toward the glutes to target the hamstrings, with secondary involvement from the calves. It's a straightforward way to build hamstring strength without hip or knee joint loading from other movements.\n\n- Lie face down with the pad resting just above the ankles and hips pressed into the bench\n- Curl the legs up by driving the heels toward the glutes\n- Squeeze the hamstrings at the top before lowering with control\n- Keep the hips pinned to the pad throughout, avoiding lifting them to cheat the weight up\n- Control the descent rather than letting the weight drop",
  "machine-chest-press": "A chest press performed on a selectorized or plate-loaded machine, guiding the arms through a fixed pressing path. It builds the chest, front delts, and triceps with a stable, controlled motion suited to higher-rep work or lifters wanting reduced stabilization demand.\n\n- Adjust the seat so the handles line up with mid-chest height\n- Grip the handles and press forward until arms are extended without locking out hard\n- Control the return until a comfortable stretch is felt across the chest\n- Keep the back and head against the pad throughout the movement\n- Avoid shrugging the shoulders up toward the ears during the press",
  "machine-crunch": "A seated, machine-guided version of the crunch that provides a fixed path of motion and adjustable resistance for isolating the abdominal muscles. It's a straightforward way to progressively overload spinal flexion with good back support.\n\n- Sit in the machine with the pads positioned according to the setup instructions\n- Engage the abs to curl the torso forward against the resistance\n- Focus on flexing the spine rather than just pushing with the arms or shoulders\n- Squeeze at the point of full contraction before returning slowly\n- Avoid letting the weight stack yank the torso back at the top",
  "machine-hip-thrust": "A guided version of the hip thrust performed on a dedicated machine, providing a fixed path and adjustable resistance to train the glutes and hamstrings through hip extension. The machine setup removes the need for balancing a barbell, allowing focus on the glute contraction.\n\n- Adjust the seat and pad so the resistance sits comfortably across your hips\n- Plant your feet flat with knees bent around ninety degrees\n- Drive through your heels, extending your hips against the pad\n- Squeeze your glutes fully at the top before lowering back down\n- Keep your core braced and avoid excessive arching of the lower back",
  "machine-lateral-raise": "A guided isolation movement performed on a dedicated machine that abducts the arms out to the sides, targeting the side delts with a fixed and supported path. The machine setup helps limit momentum and body english that can creep into free-weight versions.\n\n- Sit tall with your back against the pad and position the upper arms against the lever pads\n- Raise the arms out to the sides until roughly shoulder height, moving in a controlled arc\n- Avoid shrugging the shoulders up toward the ears as you lift\n- Squeeze briefly at the top before lowering with control\n- Adjust the seat height so the pivot point aligns with your shoulder joint",
  "machine-preacher-curl": "A machine-based version of the preacher curl that guides the arms along a fixed arc, isolating the biceps while removing the need to balance a free weight. The supported pad and consistent resistance path make it easier to focus purely on contracting the muscle through a full range.\n\n- Adjust the seat so your upper arms rest fully on the pads with elbows aligned to the pivot\n- Grip the handles and curl through a full range without shrugging the shoulders\n- Pause briefly at the top for a peak contraction\n- Lower the handles slowly rather than letting the weight stack drop\n- Keep elbows stationary on the pad throughout the movement",
  "machine-pulldown": "A guided vertical pull performed on a selectorized machine with a fixed cam path, pulling the handles down toward the chest. The fixed path makes it easier to isolate the lats without needing to stabilize free-moving cables.\n\n- Adjust the seat and thigh pads so the handles are within easy reach overhead\n- Grip the handles and keep chest lifted throughout the movement\n- Drive elbows down and back to bring the handles to chest level\n- Avoid shrugging the shoulders up toward the ears during the pull\n- Return to a full stretch with control before the next rep",
  "machine-pullover": "A seated isolation exercise using a machine with a fixed arc, pressing a handle or pad down and back in a pullover motion. It trains the lats through a controlled range without needing shoulder stabilization as in the dumbbell version.\n\n- Sit tall with back against the pad and adjust the seat so shoulders align with the machine's pivot\n- Grip the handles or place elbows on the pads as designed\n- Pull the arms down and back in an arc, driving through the lats\n- Avoid rounding the shoulders forward at the start of the movement\n- Return slowly to the stretched position before the next rep",
  "machine-row": "A guided horizontal pulling movement performed on a chest-supported or plate-loaded row machine, built to develop the upper back and lats without requiring balance or spinal stabilization. The fixed path makes it easy to focus purely on pulling mechanics and muscle contraction.\n\n- Set the chest pad and handles so shoulders sit at a comfortable pulling height\n- Drive elbows back and squeeze the shoulder blades together at the end of the pull\n- Avoid shrugging the traps up to move the weight\n- Extend arms fully under control to reset each rep\n- Keep the chest pressed into the pad throughout",
  "machine-shoulder-press": "A guided pressing movement performed on a fixed-path machine that targets the front delts and triceps while removing the need for balance or stabilization. It's a good option for adding volume to shoulder training with a lower skill demand than free weights.\n\n- Adjust the seat so the handles align with roughly shoulder height at the start\n- Press the handles up and slightly forward until your arms are extended without locking the elbows harshly\n- Keep your back flat against the pad and avoid arching to generate momentum\n- Lower the weight under control back to the starting position\n- Keep wrists stacked over the handles throughout the press",
  "meadows-row": "A unilateral barbell row performed with the bar anchored at one end (landmine-style) and pulled from the side, popularized by John Meadows, that allows a long range of motion and strong lat contraction. The angled pulling path and single-arm loading make it effective for building lat width and thickness.\n\n- Anchor one end of the barbell and stand alongside it in a staggered stance\n- Grip near the loaded end and hinge forward with a flat back\n- Pull the bar up and back toward the hip, driving the elbow high and back\n- Allow a deep stretch at the bottom of each rep before pulling again\n- Keep the torso stable and avoid twisting excessively to move the weight",
  "medicine-ball-slam": "A full-body explosive core exercise where a medicine ball is raised overhead and forcefully slammed into the ground, training the abs and lats along with total-body power output. It's a high-intensity conditioning and power movement often used to develop explosive trunk flexion.\n\n- Stand with feet shoulder-width apart holding the ball with both hands\n- Raise the ball overhead by extending through the hips and reaching tall\n- Forcefully slam the ball down by contracting the abs and pulling with the lats\n- Bend the knees slightly to absorb the motion and follow the ball down\n- Catch the ball on the bounce or pick it back up to reset each rep with control",
  "neck-curl": "An isolation exercise targeting the neck flexor muscles, typically performed lying down with light resistance such as a plate or head harness, used to build strength and size in the front of the neck. It's a low-load, controlled movement that emphasizes a limited but deliberate range of motion.\n\n- Lie on a bench with the head hanging off the edge and resistance positioned against the forehead\n- Tuck the chin and curl the head upward through a small controlled range\n- Move slowly and avoid jerking or using momentum\n- Keep the resistance light, since the neck muscles are comparatively small and sensitive to overload\n- Lower back down under control to the starting position each rep",
  "neck-extension": "This is an isolation movement that targets the posterior neck muscles by moving the head backward against resistance, typically performed lying face down on a bench with the head hanging off the edge or using manual resistance. It builds neck strength and stability by training extension through a controlled range of motion. The exercise is often used to build a thicker, stronger neck for contact sports or general muscular development.\n\n- Position yourself face down with the head and neck hanging off the edge of a bench, shoulders supported\n- Start with the chin tucked toward the chest, then extend the head back and up until the neck is in a neutral or slightly extended position\n- Move slowly and under control, avoiding jerky or ballistic motion\n- Keep the rest of the body still, isolating movement to the neck and avoiding using the shoulders or upper back to assist\n- Use light added resistance or plates only once bodyweight range of motion is controlled and comfortable",
  "neck-harness-extension": "Performed using a head harness with weight attached via a chain or strap, this exercise loads neck extension more heavily than bodyweight variations, allowing for progressive overload of the posterior neck muscles. It is commonly used by athletes seeking significant neck strength and size gains. The harness allows the head to move through extension while the rest of the body remains stable, often from a kneeling or bent-over position.\n\n- Secure the harness snugly around the head with the weight hanging behind or below depending on the setup\n- Start with the neck flexed forward, chin tucked toward the chest\n- Extend the head backward smoothly, driving the weight upward through the movement without snapping the neck\n- Control the descent back to the starting position rather than letting the weight drop\n- Keep the torso and shoulders stable throughout, isolating the motion to the neck, and start with light loads to build control before adding weight",
  "neutral-grip-dumbbell-press": "A bench press variation performed with palms facing each other throughout the movement, which can feel more comfortable on the shoulders while still building the chest and triceps. The neutral grip naturally keeps the elbows tucked closer to the torso.\n\n- Lie on a flat or slightly inclined bench with dumbbells held palms facing each other\n- Lower the dumbbells with elbows tracking close to the body rather than flaring wide\n- Press the dumbbells up in a straight line until arms are extended\n- Keep wrists straight and stacked over the elbows throughout\n- Maintain shoulder blades retracted and feet planted for stability",
  "neutral-grip-pull-up": "A vertical pulling movement using parallel handles so the palms face each other throughout the rep. This grip is often more comfortable on the shoulders while still building strong lats and biceps.\n\n- Hold the neutral handles at shoulder width, arms fully extended at the bottom\n- Brace the core to prevent excessive swinging\n- Pull by driving elbows down toward the ribs, not just bending the arms\n- Bring chest close to the handles at the top without craning the neck\n- Control the descent back to a full hang each rep",
  "nordic-ham-curl": "A demanding bodyweight hamstring exercise performed by kneeling with the ankles anchored and slowly lowering the torso forward using hamstring control, then pulling back up. It builds eccentric hamstring strength and works the glutes as stabilizers.\n\n- Anchor the ankles securely and kneel with hips fully extended\n- Lower the torso forward as slowly as possible, resisting with the hamstrings\n- Keep the hips extended throughout; avoid folding at the hips as you descend\n- Use the hands to catch and push back up if the hamstrings can no longer control the descent\n- Progress the range of motion gradually as control improves",
  "overhead-cable-triceps-extension": "This isolation exercise uses a cable and rope or straight bar attachment to work the triceps with the arms overhead, placing emphasis on the long head of the muscle due to the stretched shoulder position. It's typically performed facing away from the pulley with the cable running over the head.\n\n- Set the cable low and face away from the machine, cable running overhead\n- Keep upper arms close to your ears and stationary\n- Extend the elbows fully without flaring them outward\n- Maintain a slight forward lean and braced core for stability\n- Lower under control to feel a stretch in the triceps before extending again",
  "overhead-carry": "A loaded carry performed while holding one or two dumbbells locked out overhead, challenging shoulder stability, thoracic positioning, and core control as you walk. It builds overhead strength endurance and total-body tightness under load.\n\n- Press the dumbbell(s) fully overhead with the arm(s) locked out and biceps near the ears\n- Stack the wrist, elbow, and shoulder in a straight line before moving\n- Brace the core and avoid letting the ribs flare or the low back arch\n- Walk with controlled steps, keeping the load steady overhead without leaning\n- Lower the weight(s) safely if stability breaks down rather than fighting to keep it up",
  "overhead-press": "A standing barbell press that drives the bar from the shoulders to overhead, building pressing strength through the front delts along with heavy contribution from the triceps and upper back for stabilization. It is a foundational vertical pushing movement that also demands total-body bracing.\n\n- Set the bar at shoulder height in the rack, hands just outside shoulder width\n- Brace the core and glutes hard before initiating the press\n- Press the bar straight up, moving the head back slightly to let the bar pass, then pushing head through at the top\n- Finish with the bar over the crown of the head and arms fully locked out\n- Avoid excessive lower back arching by keeping the ribs down and core tight",
  "pallof-press": "An anti-rotation core exercise performed with a cable, where the goal is to resist the pull of the weight rather than create movement. It builds trunk stability and control against rotational and lateral forces.\n\n- Stand sideways to the cable with the handle held at the chest with both hands\n- Brace the core and press the handle straight out in front of the body\n- Resist the cable's pull to the side without letting the torso rotate\n- Hold briefly at full extension before returning to the chest with control\n- Keep hips and shoulders square throughout the movement",
  "pause-bench-press": "A bench press performed with a dead stop on the chest before pressing, removing the elastic rebound of a touch-and-go rep. This builds starting strength off the chest and forces strict control through the entire range of motion.\n\n- Lower the bar to the chest with control and let it rest there without sinking into the ribcage\n- Hold the pause for the prescribed count while keeping the chest up and shoulder blades retracted\n- Keep tension in the lats and legs during the pause rather than going fully slack\n- Drive the bar back up in a straight line without jerking or bouncing off the chest\n- Keep wrists stacked over the elbows throughout the press",
  "pause-squat": "A back squat variation that includes a deliberate pause at the bottom of the descent before standing, removing the elastic rebound and building strength out of the hole. It reinforces positional control and reinforces the quads and glutes under sustained tension.\n\n- Descend under control to at least parallel or your working depth\n- Pause for a set duration, typically one to three seconds, without shifting position\n- Keep the core braced and hips from rising during the pause\n- Maintain tightness in the upper back and avoid collapsing forward\n- Drive up explosively immediately after the pause ends",
  "pec-deck": "A machine-based isolation exercise that brings the arms together in front of the body to work the chest through a fixed, controlled arc. Because the machine stabilizes the movement path, it allows the pecs to be isolated with less involvement from stabilizing muscles.\n\n- Sit with back flat against the pad and shoulder blades pulled down and back\n- Grip the handles or place forearms on the pads at chest height\n- Bring the arms together in front of the chest, squeezing the pecs at the peak\n- Control the return to the stretched position rather than letting the weight snap back\n- Keep a slight bend in the elbows and avoid shrugging the shoulders up toward the ears",
  "pendlay-row": "A strict, explosive row performed with the torso parallel to the floor and the bar resting on the ground between reps, removing momentum and forcing each rep to start from a dead stop. This builds raw upper back and lat strength along with pulling power.\n\n- Set up with the torso bent over near parallel to the floor and the bar just off the ground\n- Grip slightly wider than shoulder width and brace the core hard before each pull\n- Pull explosively, driving elbows back to touch the bar to the lower chest or upper abdomen\n- Let the bar return fully to the floor and reset the position for every rep\n- Avoid using hip drive or momentum since each rep begins from a static dead stop",
  "pendulum-squat": "A machine squat that moves along an arcing, pendulum-style path rather than a straight line, which keeps constant tension on the quads through the entire range of motion. The design allows for a deep, controlled squat pattern with the torso supported against a pad.\n\n- Position shoulders snugly under the pads before unracking\n- Keep feet flat and shins tracking in line with the toes as you descend\n- Lower until you reach a deep, comfortable stretch on the thighs without the lower back rounding off the pad\n- Drive up smoothly, avoiding a bouncing motion at the bottom\n- Keep core braced to prevent the torso from shifting on the pad",
  "pike-push-up": "A bodyweight vertical pressing exercise performed with the hips bent and hands on the floor, shifting more load onto the front delts and triceps than a standard push-up. The steeper the hip angle, the more the movement resembles a pressing motion similar to an overhead press.\n\n- Start in a pike position with hips lifted high, hands and feet on the floor, forming an inverted V\n- Bend the elbows to lower the top of your head toward the floor between your hands\n- Keep the elbows tracking at roughly a 45-degree angle rather than flaring straight out\n- Push back up by straightening the arms and driving the head back up and away from the floor\n- Keep the core and legs braced to prevent the hips from sagging during the movement",
  "pistol-squat": "A demanding bodyweight single-leg squat, the pistol squat requires lowering on one leg while extending the other straight out in front, building quad and glute strength alongside balance and ankle mobility. It's an advanced unilateral movement that benefits from building up with easier single-leg variations first.\n\n- Stand on one leg with the other extended forward off the ground\n- Lower slowly by bending the standing knee and pushing the hips back, keeping the extended leg from touching down\n- Keep the heel of the standing foot planted throughout the descent\n- Use the arms for counterbalance as needed while keeping the chest up\n- Drive through the whole foot to stand back up without the extended leg touching the ground",
  "plank": "A bodyweight core-stability hold performed face down on the forearms and toes, keeping the body in a straight line to build isometric strength in the abs and obliques. It trains the ability to resist movement through the spine rather than producing it.\n\n- Set forearms on the floor under the shoulders and extend the legs behind, balancing on the toes\n- Keep the body in a straight line from head to heels, avoiding sagging hips or a piked-up position\n- Brace the abs as if preparing for a light blow to the stomach\n- Keep the neck neutral by looking at the floor slightly ahead of the hands\n- Breathe steadily rather than holding your breath throughout the hold",
  "plate-front-raise": "A front raise performed holding a weight plate with both hands, targeting the front delts while also engaging the grip and core to stabilize the plate. The plate is typically held by the edges and raised in front of the body.\n\n- Grip the plate at the sides with both hands, arms extended down in front\n- Raise the plate to about eye or shoulder height, keeping elbows slightly bent\n- Keep the torso upright without leaning back to generate momentum\n- Lower slowly to control the descent\n- Keep wrists neutral and the plate close to a vertical path",
  "plate-pinch": "A static grip-strength exercise where one or more weight plates are pinched together between the fingers and thumb and held for time. It isolates the thumb and finger flexors, building the pinch strength used in carrying and gripping odd objects.\n\n- Squeeze the smooth sides of the plates firmly between fingers and thumb\n- Keep the arm relaxed at your side with a neutral wrist\n- Stand tall and avoid leaning or using the body to assist the hold\n- Set a time or distance goal rather than rushing the grip\n- Lower the plate under control if grip begins to fail rather than dropping it carelessly",
  "power-clean": "An explosive full-body barbell lift where the bar is pulled from the floor and received in a partial front-rack squat, training power production, hip extension, and total-body coordination. It's a foundational Olympic-lift variation used to build explosive strength.\n\n- Start with the bar over midfoot, shins close, hips lower than shoulders, back flat\n- Pull the bar close to the body, extending hips, knees, and ankles explosively as it passes the knees\n- Shrug and pull under the bar quickly, receiving it on the front of the shoulders in a quarter-squat\n- Keep the elbows driving up and forward during the pull, then whipping around to catch the bar in the rack\n- Stand fully to complete the lift and reset before the next rep",
  "power-snatch": "A full-body Olympic lifting variant where the barbell is pulled from the floor to overhead in one continuous motion and caught in a partial squat rather than a full overhead squat. It builds explosive triatholon-style power, hip drive, and overhead stability, training nearly every major muscle group in a single rep.\n\n- Start with the bar over midfoot, hips higher than knees, back flat, and shoulders slightly ahead of the bar\n- Drive through the floor and extend hips, knees, and ankles aggressively before shrugging and pulling with the arms\n- Pull yourself under the bar quickly and catch it overhead with locked elbows in a shallow squat\n- Keep the bar close to the body throughout the pull, brushing the thighs\n- Land with active feet and a braced trunk to stabilize the overhead position",
  "preacher-curl": "A barbell curl performed with the upper arms braced against an angled preacher bench pad, which removes shoulder involvement and isolates the biceps through a strict range of motion. The fixed arm position emphasizes the stretch at the bottom and peak contraction at the top.\n\n- Rest the back of your upper arms flush against the pad, armpits near the top edge\n- Grip the bar with hands shoulder-width apart and let it lower until arms are nearly straight\n- Curl the bar up without lifting the elbows off the pad\n- Avoid bouncing out of the bottom stretch position\n- Squeeze the biceps at the top rather than jerking the weight upward",
  "pull-up": "A bodyweight vertical pulling exercise where you hang from a bar and pull your body upward until the chin clears the bar, primarily developing the lats along with the biceps and upper back. It's a foundational movement for building upper body pulling strength.\n\n- Grip the bar slightly wider than shoulder width with palms facing away\n- Start from a full hang with arms extended and shoulder blades engaged\n- Pull the elbows down and back, driving the chest toward the bar\n- Avoid excessive kipping or swinging to move the body upward\n- Lower back to a full hang under control before starting the next rep",
  "push-jerk": "An overhead pressing movement that uses a leg dip and drive to launch the bar off the shoulders before catching it overhead with locked arms in a quarter-squat, feet staying in the same parallel stance. It builds explosive power in the front delts, triceps, and quads while training rapid overhead stabilization.\n\n- Start with the bar racked on the shoulders, elbows slightly forward, feet hip-width apart\n- Dip straight down a short distance keeping the torso upright, then drive explosively upward\n- Punch the bar overhead as the legs re-bend slightly to catch it with arms locked out\n- Keep the core tight and torso vertical throughout the dip and drive\n- Stand fully upright to finish with the bar stacked over the midfoot",
  "push-press": "A vertical pressing movement that uses a slight leg dip and drive to help launch the bar overhead, allowing heavier loads to be pressed than a strict press by incorporating the quads and lower body into the initial drive. It blends explosive leg power with upper body pressing strength.\n\n- Start with the bar at the shoulders, feet about hip width apart\n- Dip straight down slightly by bending the knees, keeping the torso upright\n- Drive explosively through the legs and immediately press the bar overhead\n- Lock the arms out fully as the bar reaches the top of the path\n- Avoid leaning the torso back excessively to substitute for leg drive",
  "push-up": "A foundational bodyweight pressing exercise performed by lowering and raising the body from a plank position, building chest, triceps, and front delt strength while also demanding core and total-body stability. It requires no equipment and scales easily by changing hand placement, tempo, or body angle.\n\n- Set hands slightly wider than shoulder width with fingers pointing forward\n- Keep the body in a straight line from head to heels, bracing the core and glutes\n- Lower the chest toward the floor by bending the elbows at roughly a 45-degree angle from the torso\n- Press back up to full arm extension without letting the hips sag or pike\n- Keep the head in a neutral position, eyes looking slightly ahead rather than straight down",
  "rack-pull": "A partial deadlift performed from an elevated barbell position, typically set just below or at knee height, focusing on the top portion of the pull. This shortened range of motion allows heavier loads to be used, emphasizing the upper back and trap musculature.\n\n- Set the bar on rack pins at or just below knee height\n- Grip the bar and set your back flat with shoulders slightly ahead of the bar\n- Brace your core and drive through the floor, pulling the bar up the front of your thighs\n- Finish by extending the hips and squeezing the shoulder blades together at the top\n- Lower the bar under control back to the pins rather than dropping it",
  "reverse-curl": "A barbell curl performed with an overhand, palms-down grip, shifting emphasis onto the forearms and brachialis while still engaging the biceps. The pronated grip makes this a useful builder of forearm and grip strength alongside upper arm size.\n\n- Grip the bar overhand at shoulder width with wrists straight\n- Keep elbows tucked at your sides and curl the bar up without flaring them out\n- Avoid using a heavier load than the wrists can control, since this grip is inherently weaker\n- Curl through a full range while resisting the urge to swing the torso\n- Lower slowly to control the wrist and forearm through the descent",
  "reverse-grip-lat-pulldown": "A pulldown variation using an underhand grip on a straight bar, similar in mechanics to a chin-up but performed on a cable machine. It shifts more emphasis onto the biceps and lower lats compared to overhand grips.\n\n- Grip the bar underhand at roughly shoulder width\n- Keep chest up and lean back only slightly to maintain a straight pulling line\n- Pull the bar down toward the upper chest by driving elbows down and back\n- Squeeze the lats at the bottom rather than just bending the arms\n- Control the return to full elbow extension",
  "reverse-hyperextension": "A machine-based hinge exercise where the torso stays fixed against a pad while the legs swing from hip extension into flexion and back, isolating the glutes and lower back without loading the spine in compression. It's often used to build hip extension strength and control.\n\n- Brace the torso firmly against the pad and grip the handles for stability\n- Drive the legs up using the glutes until the body forms a straight line\n- Lower with control until hips are fully flexed, feeling a stretch through the hamstrings and glutes\n- Avoid using momentum or excessive swinging to move the weight\n- Keep the core engaged so the lower back doesn't sag mid-rep",
  "reverse-lunge": "A unilateral lunge variation where you step backward into the lunge position instead of forward, which places more emphasis on the glutes while reducing shear stress on the front knee compared to forward-stepping variations. Dumbbells add load to increase the demand on the legs.\n\n- Hold dumbbells at your sides and stand tall before stepping back\n- Step back far enough that the front knee bends to roughly ninety degrees over the ankle\n- Lower the back knee toward the floor while keeping the front shin close to vertical\n- Drive through the front heel to return to the starting standing position\n- Keep the torso upright and core braced throughout each rep",
  "reverse-pec-deck": "A machine-based isolation exercise performed facing into the pec deck pad, pulling the handles backward and out to target the rear delts and upper back. The fixed path of the machine makes it easier to isolate the rear shoulder without needing to stabilize the torso.\n\n- Sit facing the pad with chest against it and grip the handles with arms slightly bent\n- Pull the handles out and back in an arc, squeezing the shoulder blades together\n- Keep the movement controlled without jerking the weight stack\n- Avoid excessive forward lean of the torso as the arms move back\n- Return slowly to the start position, keeping tension on the rear delts",
  "reverse-wrist-curl": "A forearm isolation exercise performed with an overhand grip, extending the wrists upward against dumbbell resistance to target the forearm extensors on the top of the forearm. It's often paired with standard wrist curls to balance forearm development.\n\n- Rest your forearms on a bench or your thighs with wrists hanging just past the edge, palms facing down\n- Let the dumbbells lower toward the floor under control\n- Extend the wrists upward as far as comfortable, focusing on the top of the forearm\n- Keep the forearms anchored and avoid lifting them off the support\n- Use light weight and a slow tempo since this muscle group is easily overloaded",
  "ring-dip": "A dip performed on gymnastic rings instead of fixed bars, adding an instability component that increases demand on the chest, triceps, and stabilizing muscles around the shoulder. The free-moving rings require more control than a standard dip.\n\n- Set the rings at a height that allows full support with arms extended\n- Keep the rings turned out slightly and close to the body throughout the movement\n- Lean the torso forward and lower until the upper arms near parallel to the floor\n- Press back up while keeping the rings stable rather than letting them drift outward\n- Keep the core braced to control any swinging or instability",
  "romanian-deadlift": "The Romanian deadlift is a hip-hinge movement that starts from standing rather than the floor, emphasizing a controlled stretch through the hamstrings while keeping the knees only slightly bent. It's widely used to build hamstring and glute strength and to reinforce a solid hip-hinge pattern.\n\n- Start standing with the bar at hip height and a soft bend in the knees\n- Push the hips back while keeping the bar close to the legs and the back flat\n- Lower until you feel a stretch through the hamstrings, typically around mid-shin to knee height\n- Keep the shoulders back and avoid rounding the lower back at any point\n- Drive the hips forward to return to standing, squeezing the glutes at the top",
  "rope-pushdown": "A cable isolation move that targets the triceps through elbow extension, using a rope attachment to allow the hands to split apart at the bottom for a stronger contraction. It's a staple finisher for building triceps size and lockout strength.\n\n- Keep elbows pinned to your sides throughout the movement\n- Start with forearms parallel to the floor and extend down until arms are straight\n- Spread the rope ends apart and rotate wrists slightly at the bottom\n- Avoid leaning forward or using shoulder movement to move the weight\n- Control the eccentric back to the starting position",
  "russian-twist": "A rotational core exercise usually performed seated with feet lifted or braced, twisting a weight from side to side to train the obliques and overall trunk rotation. It's often loaded with a plate, dumbbell, or medicine ball.\n\n- Sit with knees bent and torso leaned back at roughly 45 degrees\n- Keep the chest up and spine long rather than rounding through the lower back\n- Rotate the torso to tap the weight on the floor at each side\n- Move through the trunk rather than just swinging the arms\n- Keep feet elevated for a harder version or grounded for more stability",
  "safety-bar-squat": "A squat performed with a specialty barbell that has padded shoulder yokes and front handles, shifting load slightly forward and reducing shoulder mobility demands. It trains the quads and glutes while placing extra demand on the upper back to stay tight against the bar's forward pull.\n\n- Position the yoke pads evenly across the upper traps and rear delts\n- Grip the front handles to help control the bar rather than gripping tightly with the hands on a straight bar\n- Keep the torso more upright than a low-bar squat to counter the forward shift in balance\n- Brace the upper back firmly to prevent the shoulders from rounding forward\n- Descend and drive up with the same depth and foot drive as a standard back squat",
  "sandbag-carry": "A loaded carry using an awkward, shifting sandbag held against the chest, shoulder, or in the arms, training full-body strength and stability as the load's instability constantly challenges the core and grip. The unstable nature of the sand makes this a more demanding variation than a fixed-implement carry.\n\n- Lift the sandbag using your legs and hug it securely against your torso or shoulder\n- Brace the core to control the shifting weight of the sand as you walk\n- Keep the chest up and avoid rounding through the back under the load\n- Walk with steady, even steps, adjusting grip as the bag shifts\n- Set the bag down with control rather than twisting or dropping it suddenly",
  "seal-row": "A strict prone row performed lying face-down on an elevated bench with a barbell or dumbbells underneath, eliminating any body movement so the upper back and lats do all the work. Because momentum and leg drive are completely taken out of the equation, it's one of the strictest ways to overload the back muscles directly.\n\n- Lie face-down on a raised bench with arms hanging straight down holding the bar\n- Keep the entire body flat against the bench without lifting the chest or hips\n- Pull the bar straight up toward the bench, driving elbows back\n- Squeeze the shoulder blades together at the top of each rep\n- Lower with control to a full arm extension before starting the next pull",
  "seated-barbell-overhead-press": "The seated version of the barbell overhead press removes leg drive and lower body assistance, isolating the shoulders and triceps more directly while requiring strict upper body control. It is useful for building raw pressing strength without relying on momentum from the hips or knees.\n\n- Sit upright on a bench with back flat and feet planted firmly on the floor\n- Grip the bar just outside shoulder width and set it at shoulder height\n- Press the bar straight overhead without leaning back excessively\n- Lock the elbows out fully at the top with the bar over the head\n- Lower under control back to the shoulders, keeping the torso stable throughout",
  "seated-cable-row": "A seated horizontal pull using a cable machine and handle attachment, providing constant tension throughout the range of motion to build the upper back, lats, and biceps. The fixed seating and footplate allow you to isolate the pulling muscles without relying on lower body stabilization.\n\n- Sit with knees slightly bent, feet braced on the footplate, and back upright\n- Grip the handle and let the arms extend fully to stretch the lats before pulling\n- Pull the handle toward the lower torso, driving elbows straight back\n- Squeeze the shoulder blades together at the end range without shrugging the shoulders\n- Avoid excessive leaning back or forward to add momentum to the pull",
  "seated-calf-raise": "A machine-based isolation exercise that targets the soleus by training ankle plantarflexion with the knee bent, shifting emphasis away from the gastrocnemius. It's performed seated with the pads resting on the thighs and the balls of the feet on the platform.\n\n- Lower the heels as far as comfortable to feel a stretch before driving back up\n- Rise onto the balls of the feet and pause briefly at the top\n- Keep the movement controlled rather than bouncing through the stretch\n- Avoid shifting weight onto the toes unevenly; keep pressure balanced across the foot\n- Focus on squeezing the calves at the top rather than using momentum",
  "seated-dumbbell-shoulder-press": "A seated pressing movement using dumbbells to build strength and size in the front delts, with the triceps assisting through lockout. Sitting removes lower body involvement, placing more demand on shoulder stability and unilateral control since each arm works independently.\n\n- Sit on a bench with back supported and feet flat on the floor\n- Hold dumbbells at shoulder height with palms facing forward\n- Press both dumbbells straight overhead, keeping them slightly in front of the head rather than out wide\n- Fully extend the elbows at the top without locking harshly\n- Lower the dumbbells under control back to shoulder height, keeping the core braced",
  "seated-leg-curl": "A machine isolation exercise done in a seated position that curls the lower leg backward against resistance to target the hamstrings through a stretched range of motion. The seated angle places the hamstrings in a lengthened position at the start of each rep.\n\n- Adjust the seat and pad so the knees align with the machine's pivot point\n- Curl the legs down and back by driving the heels toward the seat\n- Keep the back flat against the pad and avoid arching to generate momentum\n- Pause briefly at full contraction before returning to the stretched position\n- Lower the weight under control rather than letting it snap back",
  "side-plank": "A unilateral bodyweight hold performed on one forearm and the side of the foot, training the obliques and abs to resist lateral flexion of the spine. It builds core stability on each side independently.\n\n- Stack the feet and prop up on one forearm, elbow under the shoulder\n- Lift the hips so the body forms a straight line from head to feet\n- Keep the hips stacked and avoid rotating forward or backward\n- Brace the obliques to hold the position without sagging toward the floor\n- Keep the neck in line with the spine rather than dropping the head",
  "single-arm-cable-row": "A unilateral horizontal pulling exercise performed at a cable station, targeting the lats with strong involvement of the upper back and rear shoulder. Working one side at a time allows a deeper stretch and stronger contraction while also challenging anti-rotation core stability.\n\n- Stand or kneel facing the stack with a split stance for a stable base\n- Reach forward to feel a stretch through the lat before pulling\n- Pull the handle toward the hip, driving the elbow back and squeezing the shoulder blade\n- Keep the torso still, avoiding rotation or leaning back to move the weight\n- Control the return to full arm extension each rep",
  "single-arm-dumbbell-press": "A unilateral overhead press performed with one dumbbell at a time, which trains the front delts and triceps while forcing the obliques and core to resist rotation. It's useful for identifying and correcting strength imbalances between sides.\n\n- Press from shoulder height directly overhead, keeping the dumbbell path close to the ear\n- Brace the core hard to prevent the torso from leaning or twisting toward the working side\n- Keep the non-working hand free or lightly braced on a bench for stability if seated\n- Fully extend the elbow at the top without shrugging the shoulder up excessively\n- Lower under control back to the starting position before switching arms",
  "single-arm-lat-pulldown": "A unilateral cable pulldown performed one arm at a time using a single handle attachment. It helps address side-to-side imbalances and allows a greater stretch and contraction focus on each lat individually.\n\n- Set the cable to a height that allows a full overhead reach\n- Sit or stand with the torso stable and avoid rotating to assist the pull\n- Pull the handle down and back toward the hip, driving the elbow down\n- Keep the working shoulder blade moving down and in as you pull\n- Return slowly to a full stretch before switching sides",
  "single-leg-extension": "A unilateral variation of the leg extension that isolates the quadriceps one leg at a time, useful for correcting side-to-side strength differences and focusing on full contraction of each quad individually. The setup and execution mirror the bilateral version but with one leg working at a time.\n\n- Set the pad against the shin of the working leg and keep the other leg relaxed or braced\n- Extend the working leg fully, squeezing the quad hard at the top\n- Keep the hips level and avoid twisting the torso to assist the lift\n- Lower the weight slowly and under control\n- Match effort and range of motion between both legs across sets",
  "single-leg-press": "A unilateral variation of the leg press performed one leg at a time on the platform, which challenges the quads and glutes while exposing and addressing side-to-side strength differences. It requires more control than the bilateral version since the working leg manages the entire load.\n\n- Place the working foot centered on the platform, with the other leg resting or braced\n- Keep hips level and avoid letting the pelvis rotate as you press\n- Lower under control until the knee approaches the chest without the lower back lifting off the pad\n- Drive evenly through the whole foot to full extension without locking out hard\n- Match sets and effort across both legs",
  "single-leg-romanian-deadlift": "A unilateral hip hinge performed while balancing on one leg, holding a dumbbell in one or both hands, that builds hamstring and glute strength while challenging balance and hip stability. It's a valuable accessory for addressing side-to-side strength differences.\n\n- Stand on one leg with a slight bend in the knee, dumbbell held in the opposite or same-side hand\n- Hinge forward at the hip while extending the free leg back for counterbalance\n- Keep your hips square and torso in line with the extended leg as you lower the weight\n- Lower until you feel a stretch in the hamstring of the standing leg, then reverse the motion\n- Keep the standing knee soft and avoid letting the hips rotate open",
  "sissy-squat": "A bodyweight quad isolation exercise where you lean back while rising onto the toes and bending only at the knees, creating a long lever that intensely stretches and contracts the front of the thigh. It's typically performed holding onto a support for balance.\n\n- Hold a stable support with hands for balance throughout the movement\n- Rise onto the balls of the feet and let the knees travel forward as the torso leans back\n- Lower until you feel a deep stretch in the quads while keeping hips extended, not folding at the waist\n- Keep the movement slow and controlled rather than dropping quickly\n- Press through the balls of the feet to return to the starting position",
  "sit-up": "A full range-of-motion core exercise that brings the torso all the way up from lying to sitting, involving the abs along with hip flexors. It's a well-known bodyweight movement for building overall trunk strength and endurance.\n\n- Lie on the back with knees bent and feet anchored or flat on the floor\n- Brace the core and curl the spine to lift the torso off the ground\n- Continue until the torso is upright, then reverse the motion under control\n- Avoid yanking the neck or using the arms to throw the body upward\n- Keep movement smooth rather than using momentum to snap up",
  "smith-machine-bench-press": "A bench press performed on a Smith machine, which guides the bar along a fixed vertical track. This allows lifters to focus on pressing strength without needing to stabilize the bar path, making it useful for controlled volume work.\n\n- Set the bench so the bar path lines up over the mid-chest when unracked\n- Lower the bar under control to the chest, keeping elbows at a moderate angle\n- Press the bar back up along the fixed track until arms are extended\n- Keep feet planted and shoulder blades retracted against the bench\n- Avoid letting the wrists bend backward or the bar path pull you out of position",
  "smith-machine-calf-raise": "A standing calf raise performed with the bar racked on a Smith machine, using the guided vertical bar path to load the calves through ankle plantarflexion. A block or plate under the toes is often used to increase the range of motion.\n\n- Stand with the balls of the feet on a raised surface and heels hanging off\n- Keep the bar positioned across the upper back and torso upright\n- Lower the heels under control to feel a stretch in the calves\n- Rise fully onto the toes and pause at the top before descending\n- Keep the knees soft rather than locked throughout the set",
  "smith-machine-incline-press": "An incline press performed on a Smith machine, targeting the upper chest and front delts while the fixed bar path removes the need for balancing the load. The guided motion allows lifters to push closer to failure with reduced stabilization demand.\n\n- Set the bench to a moderate incline and position it so the bar tracks over the upper chest\n- Unrack the bar and lower it under control to the upper chest\n- Press the bar back up along the track until arms are extended without locking out harshly\n- Keep the lower back flat against the bench and avoid excessive arching\n- Keep elbows tracking under the wrists rather than flaring wide",
  "smith-machine-overhead-press": "An overhead press performed on a fixed vertical track, which trains the front delts and triceps while the machine controls the bar path. The fixed track allows you to focus purely on pressing force without managing balance.\n\n- Set the bar at upper chest to shoulder height and grip it slightly wider than shoulder width\n- Brace the core and glutes before unracking to keep the torso stable through the press\n- Press the bar straight up until the arms are fully extended, keeping wrists stacked over elbows\n- Avoid excessive lower back arching by keeping ribs down and hips under the bar\n- Lower with control back to the starting position at the same speed as the press",
  "smith-machine-row": "A horizontal row performed with the barbell fixed in a Smith machine track, offering a stable, guided path for building the upper back and lats. The fixed bar path removes the need for lateral or rotational stabilization, letting lifters focus on pulling force.\n\n- Set up bent over with a flat back, hinging from the hips\n- Pull the bar toward the lower ribs or upper abdomen\n- Drive elbows back and squeeze shoulder blades together at the top\n- Keep the torso angle steady rather than using body momentum\n- Lower the bar under control to full arm extension",
  "smith-machine-squat": "A barbell squat performed on a fixed vertical track, which removes the need to balance the bar and lets you focus on controlling depth and leg drive. It trains the quads and glutes similarly to a free squat but with a guided bar path.\n\n- Position feet slightly ahead of the bar path to keep the movement comfortable on the knees and hips\n- Keep the ribcage stacked over the pelvis and avoid excessive forward lean\n- Squat down until thighs are at least parallel, keeping heels planted\n- Push the floor away through the whole foot as you stand\n- Unhook and rehook the bar deliberately at the top and bottom of each set",
  "snatch": "A single-pull Olympic lift that takes the bar from the floor directly overhead in one explosive motion, requiring a wide grip, exceptional mobility, and full-body power and coordination. It's one of the most technically demanding barbell movements, training speed, timing, and overhead stability simultaneously.\n\n- Start with a wide grip, bar over midfoot, hips down, back flat, and shoulders slightly ahead of the bar\n- Pull the bar close to the body, extending the hips explosively as it passes the knees\n- Pull under the bar rapidly, punching the arms straight overhead as you drop into a squat\n- Catch the bar overhead with locked-out arms and an active, stable shoulder position\n- Stand up fully from the squat to complete the lift, keeping the bar balanced overhead",
  "snatch-grip-deadlift": "A deadlift performed with a wide, snatch-width grip, which increases range of motion and places greater demand on the upper back and traps to keep the torso upright. It's often used to build pulling strength and postural control under heavier stretch.\n\n- Take a wide grip on the bar, roughly where you would for a snatch\n- Set your hips lower than a conventional deadlift to accommodate the wider grip\n- Keep your chest up and lats engaged to prevent the upper back from rounding\n- Drive through the floor, keeping the bar close as it rises past the knees\n- Finish by standing tall with hips fully extended and shoulders back",
  "snatch-pull": "Similar to the clean pull but performed with the wider snatch grip, this movement trains the explosive extension and shrug used in the snatch without requiring the overhead catch. It's a strength and power builder for the traps and posterior chain under heavier-than-snatch loads.\n\n- Use a wide snatch grip with the bar over midfoot and hips set higher than in a deadlift\n- Push through the floor and extend the knees before driving the hips forward\n- Finish with an aggressive shrug and slight elbow lift, keeping the bar close to the body\n- Keep the back flat and chest up throughout the pull\n- Lower the bar under control to reset each rep with good position",
  "spider-curl": "A dumbbell curl performed while leaning chest-first over an angled bench, letting the arms hang freely in front to isolate the biceps with strict form and a strong peak contraction. This position removes the ability to swing or use the hips, forcing the biceps to do all the work.\n\n- Lean your chest against the angled pad with arms hanging straight down\n- Curl both dumbbells up while keeping upper arms vertical and still\n- Squeeze hard at the top before lowering with control\n- Let the arms fully extend at the bottom without resting the weight\n- Avoid letting the elbows drift forward or backward during the rep",
  "split-jerk": "A jerk variation where the lifter drives the bar overhead and catches it while splitting the feet front to back, allowing for greater stability and heavier overhead loads than the push jerk. It trains explosive triple extension along with front delt and quad strength in a split stance.\n\n- Dip straight down from the rack position with an upright torso, then drive the bar explosively upward\n- Split the feet quickly, front foot forward and back foot back, as the bar is punched overhead\n- Catch the bar with arms locked out and both knees slightly bent in the split stance\n- Keep the front shin vertical and back heel lifted for balance\n- Bring the feet back together under control to finish the lift standing tall",
  "split-squat": "The split squat is a stationary unilateral lunge where both feet stay planted in a split stance throughout the set, targeting the quads with glute involvement. It's a good entry point for building single-leg strength before progressing to elevated or dynamic variations.\n\n- Set up in a staggered stance with the front foot flat and the back heel lifted\n- Lower straight down by bending both knees until the back knee nearly touches the floor\n- Keep the front knee tracking in line with the toes and the torso upright\n- Distribute weight through the front foot while using the back leg for stability\n- Press through the front leg to return to the top without shifting the feet",
  "spoto-press": "A bench press variation where the bar is lowered to a stop roughly an inch above the chest without touching, then pressed back up. It builds control through the mid-range and strengthens the portion of the lift many lifters find hardest, while reinforcing tightness off the chest.\n\n- Set up with a standard bench press grip and normal arch and foot position\n- Lower the bar under control and stop just short of touching the chest\n- Hold the paused position briefly without relaxing the shoulders or losing tightness\n- Press back up in a straight line to lockout without bouncing\n- Keep the pause consistent in height every rep to build reliable positional strength",
  "standing-calf-raise": "A machine isolation exercise that raises the heels against resistance while standing to target the calf muscles through a full range of ankle motion. It's typically performed with the shoulders under pads and the balls of the feet on a raised platform.\n\n- Stand tall with the balls of the feet on the platform and heels hanging off the edge\n- Lower the heels down for a full stretch at the bottom of each rep\n- Press through the balls of the feet to rise as high as possible, squeezing the calves\n- Pause briefly at the top before lowering under control\n- Avoid bouncing at the bottom or using the knees to generate momentum",
  "standing-dumbbell-shoulder-press": "The standing version of the dumbbell shoulder press requires the abs and lower body to stabilize the body while pressing dumbbells overhead, adding a whole-body bracing component to the front delt and tricep work. Because it's standing and unilateral, it also builds core control against the offset load of each arm.\n\n- Stand with feet shoulder width apart, core braced, and dumbbells held at shoulder height\n- Press the dumbbells straight overhead without leaning back through the lower back\n- Keep the ribcage down and avoid excessive arching as the arms extend\n- Fully lock out the elbows at the top with the dumbbells over the shoulders\n- Lower with control back to the starting position, maintaining a stable stance throughout",
  "standing-leg-curl": "A unilateral machine isolation exercise that curls one leg at a time to target the hamstrings, allowing focused attention on each side independently. Working one leg at a time can help address strength imbalances between limbs.\n\n- Stand tall and position the pad just above the ankle of the working leg\n- Curl the heel toward the glute while keeping the hips square and stable\n- Avoid leaning forward or using the hips to swing the weight up\n- Squeeze the hamstring at the top of the movement before lowering slowly\n- Keep the standing leg stable and the core engaged throughout",
  "step-up": "The step-up is a unilateral exercise where you step onto an elevated platform and drive the working leg to full extension, primarily training the glutes with quad assistance. Holding dumbbells adds load while the movement builds single-leg strength useful for everyday stepping and climbing patterns.\n\n- Place one foot fully on a box or bench so the whole foot is supported\n- Drive through the heel of the working leg to stand up onto the platform\n- Avoid pushing off the trailing foot to help complete the rep\n- Keep the torso upright and hips level rather than leaning forward\n- Lower back down under control, tapping the trailing foot lightly before the next rep",
  "stiff-leg-deadlift": "A barbell hinge variation performed with minimal knee bend, emphasizing hamstring length under tension and lower back stabilization. It differs from the conventional deadlift by keeping the legs straighter throughout, shifting more work onto the hamstrings.\n\n- Set up with the bar over midfoot, knees only slightly bent\n- Hinge at the hips, pushing them back as the bar travels down the front of the legs\n- Keep the spine neutral and shoulder blades pulled back throughout the descent\n- Lower only as far as your hamstring flexibility allows while maintaining a flat back\n- Drive the hips forward to return to standing, avoiding rounding the lower back",
  "straight-arm-pulldown": "A cable isolation exercise where the arms stay nearly straight throughout, pulling a bar or rope from overhead down to the thighs. It isolates the lats without significant bicep involvement since the elbows don't bend much.\n\n- Stand facing the cable with a slight forward hinge at the hips\n- Keep arms almost fully extended with a soft bend at the elbows\n- Pull the bar down in an arc toward the thighs, leading with the upper arms\n- Focus on squeezing the lats rather than pushing with the shoulders\n- Let the bar rise back to eye level under control before repeating",
  "suitcase-carry": "A single-arm loaded carry where a dumbbell is held at one side like a suitcase, forcing the obliques and core on the loaded side to resist lateral bending while walking. It builds anti-lateral-flexion strength and grip endurance unilaterally.\n\n- Hold one dumbbell at your side with a firm grip, standing tall before you begin\n- Brace the core and resist leaning or side-bending toward the loaded hand\n- Keep both shoulders level and hips square as you walk with even steps\n- Walk a set distance or time, then switch sides and repeat evenly\n- Avoid letting the free arm swing excessively to compensate for the load",
  "sumo-deadlift": "Sumo deadlift uses a wide stance with the hands gripping inside the knees, shifting more emphasis onto the glutes and quads while still involving the hamstrings. The more upright torso position compared to conventional pulling can suit lifters with certain body proportions or those looking to reduce lower back demand.\n\n- Take a wide stance with toes turned outward and grip the bar with hands inside the knees\n- Push the knees out in the direction of the toes and keep the torso relatively upright\n- Brace the core and set the back flat before pulling\n- Drive the floor away through the whole foot, extending the hips and knees together\n- Keep the bar close to the body throughout the pull and lockout with hips fully extended",
  "svend-press": "A chest isolation movement performed by pressing a plate between the palms straight out in front of the body, using constant manual tension rather than a fixed resistance path. It works the pecs through isometric squeezing combined with a pressing motion, with minimal load but high muscle engagement.\n\n- Hold a weight plate between both palms at chest height, fingers pointing forward\n- Squeeze the plate hard between the hands throughout the entire movement\n- Press the plate straight out away from the chest until arms are extended\n- Bring the plate back to the chest under control, maintaining the squeeze\n- Keep elbows moving in a straight line and avoid letting the plate drift up or down",
  "t-bar-row": "A loaded horizontal pull using a T-bar or landmine-style bar anchored at one end, letting you pull a heavy, stable load with a close, neutral grip that emphasizes upper back thickness. The fixed pivot point makes it easier to load heavily while keeping a consistent pulling path.\n\n- Straddle the bar with a hip hinge and flat back, chest up\n- Use the handles or a V-grip attachment to keep wrists neutral\n- Pull the weight toward the lower chest or upper abdomen, leading with the elbows\n- Keep the torso angle consistent and avoid jerking the weight up with the lower back\n- Pause briefly at the top squeeze before lowering under control",
  "tate-press": "A dumbbell triceps isolation exercise performed lying on a bench with the elbows pointed out to the sides, lowering the dumbbells toward the chest by bending only at the elbow joint. This unique elbow position emphasizes a different angle of triceps tension compared to standard extensions.\n\n- Lie on a bench holding dumbbells above the chest with palms facing feet\n- Rotate elbows out to the sides so they point away from the body\n- Lower the dumbbells by bending the elbows until they touch or near the chest\n- Press back up by straightening the arms without rotating the elbows inward\n- Keep the movement slow and controlled given the shorter range of motion",
  "tempo-squat": "A back squat performed with a prescribed slow speed, often on the eccentric lowering phase, to increase time under tension and reinforce control. It builds strength and stability throughout the full range of motion by removing momentum from the lift.\n\n- Lower for a controlled count, such as three to five seconds, without pausing at the bottom\n- Keep the descent smooth and even rather than dropping quickly then slowing near the bottom\n- Maintain consistent bracing and torso angle throughout the slow phase\n- Stand up with normal or controlled speed depending on the prescribed tempo\n- Avoid letting the weight pull you out of position as fatigue builds",
  "toes-to-bar": "An advanced hanging exercise where the feet are raised all the way to touch the bar, combining hip flexion, ab strength, and lat engagement in one continuous movement. It demands more range, control, and shoulder strength than a standard leg raise.\n\n- Start from a dead hang with an active grip and engaged shoulders\n- Initiate the movement by curling the pelvis and driving the feet up in a straight line\n- Touch the bar with the toes at the top while keeping the core braced\n- Lower the legs with control rather than dropping them quickly\n- Limit swinging by keeping the lats engaged throughout the rep",
  "trap-bar-deadlift": "Performed inside a hexagonal trap bar, this deadlift variation allows a more upright torso and places greater emphasis on the quads compared to a straight bar deadlift, while still working the glutes and hamstrings. The neutral hand position and centered load make it a common alternative for building total-body pulling strength.\n\n- Stand inside the trap bar with feet roughly hip-width apart, gripping the handles at your sides\n- Set the chest up and the back flat before initiating the lift\n- Push through the floor with the legs, keeping the torso angle fairly consistent as you rise\n- Extend the hips and knees together to reach full lockout\n- Lower the bar under control by hinging and bending the knees back to the start position",
  "trap-bar-shrug": "A trap-focused shrug performed while standing inside a trap bar, using the neutral handle position to keep the arms and shoulders in a natural, low-stress line. This setup often allows heavier loading than a straight barbell shrug.\n\n- Stand centered inside the bar with a neutral grip on the handles\n- Keep arms straight and shoulders down to start each rep\n- Elevate the shoulders straight upward, avoiding a rolling motion\n- Squeeze the traps hard at the top of the movement\n- Lower the weight under control back to the starting position",
  "triceps-kickback": "A unilateral dumbbell isolation exercise where the torso is hinged forward and the upper arm is held parallel to the floor while the elbow extends the weight backward. It isolates the triceps through a short but focused range of motion at the top of the extension.\n\n- Hinge at the hips with a flat back and hold the upper arm parallel to the floor\n- Keep the elbow fixed at that height throughout the set\n- Extend the forearm back until the arm is straight, squeezing the triceps at the top\n- Avoid swinging the weight or using momentum from the shoulder\n- Lower back with control to the starting elbow angle before repeating",
  "triceps-pushdown": "A cable isolation exercise that extends the arms downward against resistance to target the triceps. It's commonly done with a straight bar, rope, or V-handle attachment on a high pulley.\n\n- Stand facing the cable stack with elbows tucked at the sides and the attachment at chest height\n- Push the attachment down until the arms are fully extended, keeping the elbows pinned to the torso\n- Avoid letting the elbows drift forward or flare out during the movement\n- Squeeze the triceps briefly at full extension\n- Control the return to the starting position without letting the weight stack slam",
  "upright-row": "A compound pulling movement that lifts a barbell straight up along the body from the thighs to around chest height, primarily working the side delts along with the traps and biceps. It combines a vertical pulling pattern with shoulder abduction.\n\n- Grip the bar with hands roughly shoulder width, arms extended down in front of the thighs\n- Pull the bar straight up along the body, leading with the elbows and keeping them above the wrists\n- Raise the bar to around chest or collarbone height without shrugging excessively\n- Keep the bar close to the body throughout the pull\n- Lower under control back to the starting position",
  "v-squat": "A plate-loaded or selectorized machine squat where the carriage moves along a V-shaped or converging track, providing a squat pattern that blends vertical and slightly forward movement. It targets the quads with strong secondary glute involvement while offering more stability than a free-standing squat.\n\n- Position feet shoulder-width apart on the platform with even weight distribution\n- Keep chest up and back in contact with the support pad throughout the movement\n- Descend under control until thighs are roughly parallel to the platform\n- Push evenly through both feet, keeping knees aligned over the toes\n- Avoid locking out aggressively or slamming the weight stack at the top",
  "viking-press": "A machine-based overhead press using parallel handles that lets you press with a neutral grip, targeting the front delts and triceps. The fixed handle path and neutral grip reduce strain on the wrists and shoulders compared to a barbell press.\n\n- Stand with the handles at shoulder height and grip firmly with palms facing each other\n- Drive through the legs slightly if the setup allows, then press the handles straight overhead\n- Keep the ribcage down and avoid excessive lower back arch as the weight passes your head\n- Extend the elbows fully at the top without shrugging the shoulders up\n- Lower the handles back to shoulder height with control",
  "walking-lunge": "A dynamic unilateral lower-body exercise performed by stepping forward into alternating lunges while holding dumbbells, training the quads, glutes, and hamstrings while also challenging balance and coordination. Each step covers ground, making it both a strength and mobility movement.\n\n- Hold dumbbells at your sides with a tall, upright torso\n- Step forward far enough that the front knee tracks over the ankle, not past the toes\n- Lower the back knee toward the ground under control, keeping the front shin close to vertical\n- Push through the front heel to rise and step into the next lunge\n- Keep the core braced to avoid excessive torso lean or twisting",
  "wall-sit": "A static bodyweight hold where you sit against a wall with knees bent near ninety degrees, keeping the quads under continuous tension without any joint movement. It's used to build isometric strength and muscular endurance in the front of the thighs.\n\n- Press your back flat against the wall with feet positioned far enough out that knees sit roughly above the ankles\n- Lower until thighs are close to parallel with the floor, forming a right angle at the knees\n- Keep weight distributed through the whole foot rather than rising onto the toes\n- Brace the core and keep breathing steady throughout the hold\n- Hold the position for the target duration without shifting or bouncing",
  "weighted-chest-dip": "A loaded version of the chest dip performed with added resistance from a dip belt, weight vest, or held dumbbell, increasing demand on the chest, triceps, and front delts beyond bodyweight alone. It's used to keep progressing strength once bodyweight dips become manageable for high reps.\n\n- Attach the weight securely before starting so it doesn't swing during the set\n- Lean the torso forward and lower until the upper arms approach parallel to the floor\n- Keep elbows tracking slightly outward and shoulders down away from the ears\n- Press back to full extension under control without bouncing at the bottom\n- Choose an added load that still allows full range of motion with good control",
  "weighted-pull-up": "A progression of the standard pull-up where additional load is added via a belt, vest, or held dumbbell, increasing the demand on the lats and biceps for building pulling strength and muscle size. It's used once bodyweight pull-ups become too easy for continued progress.\n\n- Attach weight securely via a dip belt, vest, or between the feet before starting\n- Begin from a full dead hang with shoulder blades set\n- Pull the elbows down and back, leading with the chest toward the bar\n- Keep the body controlled without excessive swinging to manage the added load\n- Lower fully under control each rep to maintain a complete range of motion",
  "weighted-push-up": "A progression of the standard push-up where external load, such as a plate or weighted vest, is added to increase resistance beyond bodyweight. It develops the same horizontal pressing pattern for the chest and triceps but allows continued strength gains once bodyweight reps become too easy.\n\n- Position the added weight securely on the upper back so it doesn't shift during reps\n- Maintain a rigid plank position from head to heels throughout the movement\n- Lower under control until the chest nears the floor, keeping elbows at roughly a 45-degree angle\n- Press back to full extension without letting the hips drop or rise first\n- Start with a modest added load and prioritize full range of motion over heavier weight",
  "wide-grip-lat-pulldown": "A variation of the lat pulldown using a wider-than-shoulder grip to emphasize the outer lats and upper back through a shorter range of elbow motion. It reduces bicep involvement compared to closer grips.\n\n- Grip the bar well outside shoulder width with palms facing away\n- Keep the chest lifted and avoid leaning back excessively to use momentum\n- Pull the bar down to the upper chest by driving the elbows out and down\n- Squeeze the shoulder blades together at the bottom of the movement\n- Return to a full stretch overhead with control",
  "wide-grip-seated-row": "A cable row variation using a wide bar attachment and a wider grip, which shifts emphasis toward the upper back and rear delts by encouraging a higher elbow path. It's a useful variation for targeting the mid and upper back musculature differently than a standard narrow-grip row.\n\n- Sit tall with feet braced and knees slightly bent, gripping the wide bar with hands wider than shoulder width\n- Pull the bar toward the upper abdomen or lower chest, driving elbows out and back\n- Keep the elbows elevated relative to the torso to bias the rear delts and upper back\n- Squeeze the shoulder blades together at the peak of the pull\n- Control the return to a full stretch without letting the torso lean excessively forward",
  "wrist-curl": "A forearm isolation exercise performed by resting the forearms on a bench or thighs and curling a barbell upward using only wrist flexion. It targets the forearm flexors and is commonly used to build grip and forearm size.\n\n- Rest your forearms on a bench or your thighs with wrists hanging just past the edge\n- Hold the bar with an underhand grip and let it roll down toward your fingertips\n- Curl the bar up by flexing the wrists as high as possible\n- Keep the forearms pressed down and still throughout the movement\n- Use a controlled tempo rather than jerking or bouncing the weight up",
  "wrist-roller": "A dedicated forearm builder using a handle with a hanging weight attached by a cord, rolled up and down through wrist flexion and extension. It targets the muscles of the forearm responsible for grip strength and wrist control, building both size and endurance in the lower arms.\n\n- Hold the roller with arms extended straight out in front at shoulder height\n- Roll the handle continuously with wrist motion, not by swinging the arms\n- Alternate rolling forward to lift the weight and controlling it back down\n- Keep shoulders and elbows relatively still throughout\n- Use a weight light enough to complete full rolls without resting mid-set",
  "yates-row": "A row variation popularized by Dorian Yates, performed with a more upright torso angle and an underhand or overhand grip, shifting emphasis toward the lats while still building overall back thickness. The reduced torso lean allows for heavier loading with less lower back strain relative to a standard bent-over row.\n\n- Set up with the torso at roughly a 45-60 degree angle, more upright than a traditional barbell row\n- Use an underhand grip if targeting lats more directly, or overhand for a broader back emphasis\n- Pull the bar toward the hips or lower abdomen, driving elbows back and slightly in\n- Keep the torso angle locked in place and avoid standing up to move the weight\n- Control the descent fully rather than dropping the bar between reps",
  "yoke-walk": "A strongman-style carry where a heavy frame is loaded across the back and shoulders and walked for distance, training total-body bracing, leg drive, and upper back stability under a heavy compressive load. It demands coordination between the legs, trunk, and upper back to move efficiently.\n\n- Position yourself under the yoke so the load sits evenly across the upper back and shoulders\n- Brace the core hard and stand up fully before beginning to walk\n- Take short, quick, controlled steps rather than long strides\n- Keep the chest up and avoid letting the frame rock side to side\n- Set the load down under control at the finish, keeping the back braced",
  "z-press": "An overhead press performed seated on the floor with legs extended straight out, removing all leg drive and lower body assistance to demand strict pressing strength and a rigid upper body. The seated floor position heavily engages the abs and core to keep the torso upright while pressing.\n\n- Sit on the floor with legs extended straight in front, back upright\n- Set the bar at shoulder height and grip just outside shoulder width\n- Brace the abs hard to keep the torso vertical without leaning back\n- Press the bar straight overhead to full lockout\n- Lower under control back to the shoulders while maintaining the upright seated position",
  "zercher-squat": "A squat where the barbell is held in the crooks of the elbows against the front of the body, rather than on the back or shoulders. This front-loaded position heavily engages the core and upper back for support while still driving strength through the quads and glutes.\n\n- Cradle the bar in the bend of the elbows, holding hands together for support\n- Keep the torso as upright as possible to keep the bar close to the body\n- Brace the abs hard since the load pulls the torso forward\n- Squat down keeping the elbows tucked in and bar path close and vertical\n- Drive up through the whole foot while maintaining an upright chest",
};
